dated_at();\n\n-- ---------------------------------------------------------------------------\n-- Publicações: UMA por oferta e destino. Idempotência garantida pelo banco.\n-- ---------------------------------------------------------------------------\ncreate table public.publications (\n  id                  uuid primary key default gen_random_uuid(),\n  offer_id            uuid not null references public.offers (id) on delete cascade,\n  destination_id      uuid not null references public.destinations (id) on delete restrict,\n  content_version     integer not null default 1,\n  rendered_text       text not null,\n  status              text not null default 'pending'\n                      check (status in ('pending', 'claimed', 'sent', 'retry_scheduled',\n                                        'failed_permanent', 'unknown', 'cancelled')),\n  idempotency_key     text not null unique,\n  attempt_count       integer not null default 0,\n  scheduled_for       timestamptz not null default now(),\n  next_attempt_at     timestamptz not null default now(),\n  claimed_at          timestamptz,\n  locked_by           text,\n  locked_until        timestamptz,\n  external_message_id text,\n  last_error_code     text,\n  note                text,\n  sent_at             timestamptz,\n  created_at          timestamptz not null default now(),\n  updated_at          timestamptz not null default now(),\n  unique (offer_id, destination_id, content_version)\n);\ncreate index publications_queue_idx on public.publications (status, next_attempt_at);\ncreate index publications_dest_idx on public.publications (destination_id, status);\ncreate trigger trg_publications_updated before update on public.publications\n  for each row execute function public.set_updated_at();\n\n-- ---------------------------------------------------------------------------\n-- Redirecionador e cliques (visitante só como hash; sem IP nem telefone)\n-- ---------------------------------------------------------------------------\ncreate table public.short_links (\n  code           text primary key,\n  publication_id uuid not null references public.publications (id) on delete cascade,\n  target_url     text not null,\n  disabled       boolean not null default false,\n  created_at     timestamptz not null default now()\n);\n\ncreate table public.click_events (\n  id            bigint generated always as identity primary key,\n  code          text not null references public.short_links (code) on delete cascade,\n  clicked_at    timestamptz not null default now(),\n  visitor_hash  text,\n  ua_family     text,\n  referrer_host text\n);\ncreate index click_events_time_idx on public.click_events (clicked_at desc);\ncreate index click_events_code_idx on public.click_events (code);\n\n-- ---------------------------------------------------------------------------\n-- Auditoria, execuções de coleta, configurações e batimentos de serviço\n-- ---------------------------------------------------------------------------\ncreate table public.audit_events (\n  id          bigint generated always as identity primary key,\n  actor_type  text not null check (actor_type in ('system', 'admin')),\n  actor_id    uuid,\n  action      text not null,\n  entity_type text,\n  entity_id   text,\n  metadata    jsonb not null default '{}'::jsonb,\n  created_at  timestamptz not null default now()\n);\ncreate index audit_time_idx on public.audit_events (created_at desc);\ncreate index audit_entity_idx on public.audit_events (entity_type, entity_id);\n\ncreate table public.runs (\n  id             uuid primary key default gen_random_uuid(),\n  connector_id   uuid not null references public.connectors (id) on delete cascade,\n  started_at     timestamptz not null default now(),\n  finished_at    timestamptz,\n  status         text not null default 'running' check (status in ('running', 'success', 'partial', 'error')),\n  items_seen     integer not null default 0,\n  items_accepted integer not null default 0,\n  items_rejected integer not null default 0,\n  error_summary  text\n);\ncreate index runs_time_idx on public.runs (started_at desc);\n\ncreate table public.settings (\n  key        text primary key,\n  value      jsonb not null,\n  updated_by uuid,\n  updated_at timestamptz not null default now()\n);\n\ncreate table public.heartbeats (\n  service   text primary key,\n  last_seen timestamptz not null default now(),\n  status    text not null default 'ok' check (status in ('ok', 'degraded', 'down')),\n  details   jsonb not null default '{}'::jsonb\n);\n"},{"version":"002_core_functions.sql","sql":"-- ============================================================================\n-- 002_core_functions.sql — regras que NÃO podem falhar ficam no banco.\n-- Chamadores humanos (painel) usam o papel `authenticated` e passam por RBAC.\n-- O n8n usa `service_role` (auth.uid() nulo). `anon` nunca executa nada.\n-- ============================================================================\n\n-- ---------- Helpers de acesso ----------------------------------------------\ncreate or replace function public.app_role() returns text\nlanguage sql stable security definer set search_path = public as $$\n  select role from public.profiles where user_id = auth.uid() and active\n$$;\n\ncreate or replace function public.is_admin() returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce(public.app_role() = 'admin', false)\n$$;\n\ncreate or replace function public.can_operate() returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce(public.app_role() in ('admin', 'operator'), false)\n$$;\n\ncreate or replace function public.is_member() returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select public.app_role() is not null\n$$;\n\n-- Humano sem permissão é barrado; service_role (auth.uid() nulo) passa.\ncreate or replace function public.require_operator() returns void\nlanguage plpgsql stable security definer set search_path = public as $$\nbegin\n  if auth.uid() is not null and not public.can_operate() then\n    raise exception 'Permissão negada: requer perfil operador ou administrador' using errcode = '42501';\n  end if;\nend $$;\n\ncreate or replace function public.require_admin() returns void\nlanguage plpgsql stable security definer set search_path = public as $$\nbegin\n  if auth.uid() is not null and not public.is_admin() then\n    raise exception 'Permissão negada: requer perfil administrador' using errcode = '42501';\n  end if;\nend $$;\n\n-- ---------- Configurações ---------------------------------------------------\ncreate or replace function public.setting(p_key text) returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  select value from public.settings where key = p_key\n$$;\n\ncreate or replace function public.setting_int(p_key text, p_default integer) returns integer\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce((select (value #>> '{}')::integer from public.settings where key = p_key), p_default)\n$$;\n\ncreate or replace function public.setting_bool(p_key text, p_default boolean) returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce((select (value #>> '{}')::boolean from public.settings where key = p_key), p_default)\n$$;\n\ncreate or replace function public.setting_text(p_key text, p_default text) returns text\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce((select value #>> '{}' from public.settings where key = p_key), p_default)\n$$;\n\n-- ---------- Auditoria (com redação de segredos) -----------------------------\ncreate or replace function public.scrub(p jsonb) returns jsonb\nlanguage sql immutable as $$\n  select coalesce(\n    jsonb_object_agg(\n      k,\n      case when k ~* '(token|secret|password|senha|api_?key|cookie|authorization)'\n           then '\"[redigido]\"'::jsonb else v end),\n    '{}'::jsonb)\n  from jsonb_each(coalesce(p, '{}'::jsonb)) as t(k, v)\n$$;\n\ncreate or replace function public.log_audit(\n  p_action text, p_entity_type text default null, p_entity_id text default null,\n  p_meta jsonb default '{}'::jsonb\n) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  insert into public.audit_events (actor_type, actor_id, action, entity_type, entity_id, metadata)\n  values (case when auth.uid() is null then 'system' else 'admin' end,\n          auth.uid(), p_action, p_entity_type, p_entity_id, public.scrub(p_meta));\nend $$;\n\n-- Trigger genérico: registra alterações feitas diretamente em tabelas de configuração.\ncreate or replace function public.audit_row_change() returns trigger\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  v_old jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end;\n  v_new jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end;\n  v_row jsonb := coalesce(v_new, v_old);\n  v_changed jsonb := '{}'::jsonb;\n  k text;\nbegin\n  if tg_op = 'UPDATE' then\n    for k in select jsonb_object_keys(v_new) loop\n      if k <> 'updated_at' and (v_old -> k) is distinct from (v_new -> k) then\n        v_changed := v_changed || jsonb_build_object(k, jsonb_build_object('de', v_old -> k, 'para', v_new -> k));\n      end if;\n    end loop;\n    if v_changed = '{}'::jsonb then return new; end if;\n  elsif tg_op = 'INSERT' then\n    v_changed := public.scrub(v_new);\n  else\n    v_changed := public.scrub(v_old);\n  end if;\n  perform public.log_audit(\n    lower(tg_op) || '_' || tg_table_name, tg_table_name,\n    coalesce(v_row ->> 'id', v_row ->> 'user_id', v_row ->> 'key'),\n    jsonb_build_object('campos', v_changed));\n  return coalesce(new, old);\nend $$;\n\n-- ---------- Utilitários de URL e texto --------------------------------------\ncreate or replace function public.url_host(p_url text) returns text\nlanguage sql immutable as $$\n  select lower(substring(p_url from '^https?://([^/:?#@]+)(?::[0-9]+)?(?:[/?#]|$)'))\n$$;\n\ncreate or replace function public.normalize_url(p_url text) returns text\nlanguage sql immutable as $$\n  select case when public.url_host(p_url) is null then null\n    else 'https://' || public.url_host(p_url) ||\n         regexp_replace(coalesce(substring(split_part(split_part(p_url, '#', 1), '?', 1)\n                                           from '^https?://[^/]+(/.*)$'), ''), '/+$', '')\n  end\n$$;\n\n-- Melhor esforço: o ID externo só ajuda na deduplicação. Se não casar, retorna nulo.\ncreate or replace function public.extract_external_id(p_platform text, p_url text) returns text\nlanguage sql immutable as $$\n  select case p_platform\n    when 'amazon' then upper(substring(p_url from '/(?:dp|gp/product)/([A-Za-z0-9]{10})'))\n    when 'mercadolivre' then replace(upper(substring(p_url from '(?i)(MLB-?[0-9]+)')), '-', '')\n    when 'shopee' then substring(p_url from 'i\\.([0-9]+\\.[0-9]+)')\n  end\n$$;\n\ncreate or replace function public.host_allowed(p_platform text, p_url text) returns boolean\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce((\n    select bool_or(public.url_host(p_url) = lower(d) or right(public.url_host(p_url), length(d) + 1) = '.' || lower(d))\n    from jsonb_array_elements_text(coalesce(public.setting('allowed_domains') -> p_platform, '[]'::jsonb)) as t(d)\n    where public.url_host(p_url) is not null\n  ), false)\n$$;\n\ncreate or replace function public.fmt_brl(p_value numeric) returns text\nlanguage sql immutable as $$\n  select 'R$ ' || replace(replace(replace(to_char(p_value, 'FM999,999,990.00'), ',', '#'), '.', ','), '#', '.')\n$$;\n\ncreate or replace function public.text_violations(p_text text) returns text[]\nlanguage sql stable security definer set search_path = public as $$\n  select coalesce(array_agg(t), '{}')\n  from jsonb_array_elements_text(coalesce(public.setting('banned_terms'), '[]'::jsonb)) as x(t)\n  where p_text ~* ('\\m' || regexp_replace(t, '([.^$*+?()\\[\\]{}|\\\\])', '\\\\\\1', 'g') || '\\M')\n$$;\n\n-- ---------- Histórico próprio de preço --------------------------------------\n-- Só vira \"preço anterior\" se houver observações suficientes de fonte confiável.\ncreate or replace function public.own_history_previous(p_product uuid) returns numeric\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare\n  v_min_obs integer := public.setting_int('min_history_observations', 5);\n  v_min_days integer := public.setting_int('min_history_days', 3);\n  v_count integer; v_days integer; v_max numeric;\nbegin\n  select count(*), count(distinct (observed_at at time zone 'America/Sao_Paulo')::date), max(price)\n    into v_count, v_days, v_max\n  from public.price_observations\n  where product_id = p_product\n    and source_kind in ('api', 'feed')\n    and observed_at > now() - interval '30 days';\n  if v_count >= v_min_obs and v_days >= v_min_days then return v_max; end if;\n  return null;\nend $$;\n\n-- ---------- Pontuação --------------------------------------------------------\ncreate or replace function public.score_offer(p_offer uuid) returns integer\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  o record; obs record;\n  v_score integer := 0; v_reasons jsonb := '[]'::jsonb; v_age numeric; v_pts integer;\nbegin\n  select * into o from public.offers where id = p_offer;\n  if not found then raise exception 'oferta inexistente'; end if;\n  select * into obs from public.price_observations where id = o.observation_id;\n\n  -- Confiança da fonte (até 40)\n  v_pts := case obs.source_kind when 'api' then 40 when 'feed' then 30 else 20 end;\n  v_score := v_score + v_pts;\n  v_reasons := v_reasons || jsonb_build_object('code', 'source', 'points', v_pts,\n    'label', case obs.source_kind when 'api' then 'Fonte oficial (API)' when 'feed' then 'Feed de oferta'\n                                  else 'Dado declarado por você' end);\n\n  -- Frescor do dado (até 20)\n  v_age := extract(epoch from (now() - o.price_observed_at)) / 60;\n  v_pts := case when v_age <= 60 then 20 when v_age <= 360 then 10 else 0 end;\n  v_score := v_score + v_pts;\n  v_reasons := v_reasons || jsonb_build_object('code', 'freshness', 'points', v_pts,\n    'label', case when v_pts = 20 then 'Preço observado há menos de 1 h'\n                  when v_pts = 10 then 'Preço observado há menos de 6 h'\n                  else 'Dado com mais de 6 h' end);\n\n  -- Desconto comprovado (até 35): 1 ponto por 1 % de queda\n  if o.discount_pct is not null then\n    v_pts := least(35, floor(o.discount_pct))::integer;\n    v_score := v_score + v_pts;\n    v_reasons := v_reasons || jsonb_build_object('code', 'discount', 'points', v_pts,\n      'label', 'Queda de ' || o.discount_pct || '% (' ||\n               case o.previous_price_source when 'own_history' then 'histórico próprio' else 'fonte oficial' end || ')');\n  else\n    v_reasons := v_reasons || jsonb_build_object('code', 'discount', 'points', 0,\n      'label', 'Sem desconto comprovado');\n  end if;\n\n  -- Link de afiliado válido (5)\n  if o.affiliate_url is not null and public.host_allowed(\n       (select platform from public.products where id = o.product_id), o.affiliate_url) then\n    v_score := v_score + 5;\n    v_reasons := v_reasons || jsonb_build_object('code', 'link', 'points', 5, 'label', 'Link de afiliado presente');\n  else\n    v_reasons := v_reasons || jsonb_build_object('code', 'link', 'points', 0,\n      'label', 'Link de afiliado ausente ou não confirmado');\n  end if;\n\n  v_score := least(100, v_score);\n  update public.offers set score = v_score, score_reasons = v_reasons where id = p_offer;\n  return v_score;\nend $$;\n\n-- ---------- Entrada única de ofertas (painel manual e n8n) -------------------\ncreate or replace function public.ingest_offer(p jsonb) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  v_platform text := p ->> 'platform';\n  v_orig text := nullif(btrim(p ->> 'original_url'), '');\n  v_aff text := nullif(btrim(coalesce(p ->> 'affiliate_url', '')), '');\n  v_title text := nullif(btrim(coalesce(p ->> 'title', '')), '');\n  v_price numeric := nullif(p ->> 'price', '')::numeric;\n  v_prev numeric := nullif(p ->> 'previous_price', '')::numeric;\n  v_kind text := coalesce(p ->> 'source_kind', 'admin_declared');\n  v_layer text := coalesce(p ->> 'source_layer', 'A');\n  v_obs_at timestamptz := coalesce(nullif(p ->> 'observed_at', '')::timestamptz, now());\n  v_avail text := coalesce(p ->> 'availability', 'unknown');\n  v_expires timestamptz := nullif(p ->> 'expires_at', '')::timestamptz;\n  v_sim boolean := coalesce((p ->> 'is_simulated')::boolean, false);\n  v_max_age integer := public.setting_int('max_price_age_minutes', 720);\n  v_window integer := public.setting_int('dedupe_window_hours', 72);\n  v_drop numeric := public.setting_int('republish_drop_pct', 10);\n  v_fail jsonb := '[]'::jsonb; v_notes jsonb := '[]'::jsonb;\n  v_canon text; v_ext text; v_product uuid; v_obs bigint; v_offer uuid;\n  v_prev_final numeric; v_prev_src text; v_disc numeric; v_hist numeric;\n  v_existing record; v_last record; v_score integer;\nbegin\n  perform public.require_operator();\n\n  if v_platform is null or v_platform not in ('mercadolivre', 'shopee', 'amazon') then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'platform_invalid', 'message', 'Plataforma inválida'));\n  end if;\n  if v_title is null or length(v_title) > 300 then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'title_invalid', 'message', 'Título ausente ou maior que 300 caracteres'));\n  end if;\n  if v_orig is null or not public.host_allowed(v_platform, v_orig) then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'domain_not_allowed', 'message', 'URL do produto fora dos domínios permitidos da plataforma'));\n  end if;\n  if v_aff is not null and not public.host_allowed(v_platform, v_aff) then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'affiliate_host_not_allowed', 'message', 'Link de afiliado fora dos domínios permitidos (confirme o domínio oficial e cadastre em Configurações)'));\n  end if;\n  if v_price is null or v_price <= 0 then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'price_invalid', 'message', 'Preço ausente ou não positivo'));\n  end if;\n  if v_kind not in ('api', 'feed', 'admin_declared') then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'source_invalid', 'message', 'Tipo de fonte inválido'));\n  end if;\n  if v_avail not in ('in_stock', 'out_of_stock', 'unknown') then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'availability_invalid', 'message', 'Disponibilidade inválida'));\n  elsif v_avail = 'out_of_stock' then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'out_of_stock', 'message', 'Produto sem estoque'));\n  end if;\n  if v_obs_at > now() + interval '5 minutes' then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'observed_in_future', 'message', 'Horário da observação no futuro'));\n  elsif extract(epoch from (now() - v_obs_at)) / 60 > v_max_age then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'price_too_old', 'message', 'Preço observado há mais de ' || v_max_age || ' min'));\n  end if;\n  if v_expires is not null and v_expires <= now() then\n    v_fail := v_fail || jsonb_build_array(jsonb_build_object('code', 'expired', 'message', 'Oferta já vencida'));\n  end if;\n\n  if jsonb_array_length(v_fail) > 0 then\n    perform public.log_audit('offer_ingest_rejected', 'offer', null,\n      jsonb_build_object('plataforma', v_platform, 'titulo', left(coalesce(v_title, ''), 80),\n                         'host', public.url_host(v_orig), 'falhas', v_fail));\n    return jsonb_build_object('status', 'rejected', 'failures', v_fail);\n  end if;\n\n  v_canon := public.normalize_url(v_orig);\n  v_ext := coalesce(nullif(p ->> 'external_id', ''), public.extract_external_id(v_platform, v_orig));\n\n  select id into v_product from public.products\n   where platform = v_platform\n     and ((v_ext is not null and external_id = v_ext) or canonical_url = v_canon)\n   limit 1;\n\n  if v_product is not null then\n    select id, status into v_existing from public.offers\n     where product_id = v_product and status in ('discovered', 'needs_review', 'approved', 'scheduled')\n     order by created_at desc limit 1;\n    if found then\n      return jsonb_build_object('status', 'duplicate', 'reason', 'open_offer', 'offer_id', v_existing.id);\n    end if;\n\n    select o.id, o.current_price into v_last\n      from public.offers o\n      join public.publications pu on pu.offer_id = o.id and pu.status in ('pending', 'claimed', 'sent', 'unknown', 'retry_scheduled')\n     where o.product_id = v_product and pu.created_at > now() - make_interval(hours => v_window)\n     order by pu.created_at desc limit 1;\n    if found and not (v_price <= v_last.current_price * (1 - v_drop / 100.0)) then\n      return jsonb_build_object('status', 'duplicate', 'reason', 'recently_published', 'offer_id', v_last.id);\n    elsif found then\n      v_notes := v_notes || jsonb_build_array('Republicação permitida: queda material de preço desde o último envio');\n    end if;\n\n    update public.products set\n      title = v_title,\n      category = coalesce(nullif(p ->> 'category', ''), category),\n      image_url = coalesce(nullif(p ->> 'image_url', ''), image_url),\n      seller_name = coalesce(nullif(p ->> 'seller_name', ''), seller_name)\n     where id = v_product;\n  else\n    insert into public.products (platform, external_id, canonical_url, title, category, image_url, seller_name)\n    values (v_platform, v_ext, v_canon, v_title, nullif(p ->> 'category', ''),\n            nullif(p ->> 'image_url', ''), nullif(p ->> 'seller_name', ''))\n    returning id into v_product;\n  end if;\n\n  -- Preço anterior: só de fonte confiável (API/feed) ou do histórico próprio.\n  if v_kind in ('api', 'feed') and v_prev is not null and v_prev > v_price then\n    v_prev_final := v_prev; v_prev_src := v_kind;\n  else\n    if v_prev is not null and v_kind = 'admin_declared' then\n      v_notes := v_notes || jsonb_build_array('Preço anterior declarado manualmente foi ignorado (fonte não confiável)');\n    end if;\n    v_hist := public.own_history_previous(v_product);\n    if v_hist is not null and v_hist > v_price then\n      v_prev_final := v_hist; v_prev_src := 'own_history';\n    end if;\n  end if;\n  if v_prev_final is not null then\n    v_disc := least(99.99, round((v_prev_final - v_price) / v_prev_final * 100, 2));\n  end if;\n\n  insert into public.price_observations\n    (product_id, price, claimed_previous_price, availability, source_kind, source_name, observed_at, evidence)\n  values (v_product, v_price, v_prev, v_avail, v_kind, p ->> 'source_name', v_obs_at,\n          public.scrub(coalesce(p -> 'evidence', '{}'::jsonb)))\n  returning id into v_obs;\n\n  if v_aff is null then\n    v_notes := v_notes || jsonb_build_array('Link de afiliado ausente: obtenha no painel oficial antes de aprovar');\n  end if;\n\n  insert into public.offers\n    (product_id, observation_id, status, source_layer, source_name, original_url, affiliate_url,\n     current_price, previous_price, previous_price_source, discount_pct, coupon_code, coupon_confirmed,\n     availability, price_observed_at, expires_at, validation_notes, is_simulated, created_by)\n  values (v_product, v_obs, 'needs_review', v_layer, p ->> 'source_name', v_orig, v_aff,\n          v_price, v_prev_final, v_prev_src, v_disc, nullif(p ->> 'coupon_code', ''),\n          nullif(p ->> 'coupon_code', '') is not null\n            and (v_kind in ('api', 'feed') or coalesce((p ->> 'coupon_confirmed')::boolean, false)),\n          v_avail, v_obs_at, v_expires, v_notes, v_sim, auth.uid())\n  returning id into v_offer;\n\n  v_score := public.score_offer(v_offer);\n  perform public.log_audit('offer_ingested', 'offer', v_offer::text,\n    jsonb_build_object('plataforma', v_platform, 'camada', v_layer, 'fonte', v_kind, 'score', v_score,\n                       'simulada', v_sim));\n  return jsonb_build_object('status', 'created', 'offer_id', v_offer, 'score', v_score, 'notes', v_notes);\nend $$;\n\n-- ---------- Renderização (prévia = exatamente o que será enviado) -----------\ncreate or replace function public.render_offer_text(\n  p_offer uuid, p_destination uuid, p_short_code text default null\n) returns text\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare\n  o record; pr record; d record; c record;\n  t text; v_vars jsonb; v_line text; v_out text[] := '{}'; v_drop boolean; v_res text; m record;\n  v_val text; v_base text; v_url text; v_prevline text; v_disc text; v_esc boolean; v_tz text := 'America/Sao_Paulo';\nbegin\n  select * into o from public.offers where id = p_offer;\n  select * into d from public.destinations where id = p_destination;\n  if o.id is null or d.id is null then raise exception 'oferta ou destino inexistente'; end if;\n  select * into pr from public.products where id = o.product_id;\n  select * into c from public.connectors where platform = pr.platform;\n  select body into t from public.templates where channel = d.channel and kind = 'offer' and active;\n  if t is null then raise exception 'Sem template ativo de oferta para %', d.channel; end if;\n\n  v_base := public.setting_text('shortlink_base', '');\n  if coalesce(c.use_short_link, true) and v_base <> '' then\n    v_url := rtrim(v_base, '/') || '/' || coalesce(p_short_code, 'abc123xy');\n  else\n    v_url := o.affiliate_url;\n  end if;\n\n  v_prevline := '';\n  if o.previous_price is not null and o.discount_pct is not null then\n    v_prevline := case o.previous_price_source\n      when 'own_history' then 'Já registramos por ' || public.fmt_brl(o.previous_price)\n      else 'Antes: ' || public.fmt_brl(o.previous_price) end\n      || ' (-' || trim(trailing '.' from trim(trailing '0' from o.discount_pct::text)) || '%)';\n  end if;\n\n  v_vars := jsonb_build_object(\n    'title', pr.title,\n    'price', public.fmt_brl(o.current_price),\n    'previous_line', v_prevline,\n    'coupon_line', case when o.coupon_code is not null and o.coupon_confirmed then 'Cupom: ' || o.coupon_code else '' end,\n    'observed_at', to_char(o.price_observed_at at time zone v_tz, 'DD/MM \"às\" HH24:MI'),\n    'url', coalesce(v_url, ''),\n    'disclosure', public.setting_text('affiliate_disclosure', ''),\n    'category', coalesce(pr.category, ''),\n    'seller', coalesce(pr.seller_name, ''));\n\n  v_esc := d.channel = 'telegram';\n  foreach v_line in array string_to_array(t, E'\\n') loop\n    v_drop := false; v_res := v_line;\n    for m in select distinct (regexp_matches(v_line, '\\{\\{([a-z_]+)\\}\\}', 'g'))[1] as name loop\n      v_val := coalesce(v_vars ->> m.name, '');\n      if v_val = '' then v_drop := true; exit; end if;\n      if v_esc then\n        v_val := replace(replace(replace(replace(v_val, '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '\"', '&quot;');\n      end if;\n      v_res := replace(v_res, '{{' || m.name || '}}', v_val);\n    end loop;\n    if not v_drop then v_out := v_out || v_res; end if;\n  end loop;\n\n  v_res := array_to_string(v_out, E'\\n');\n  if position('{{disclosure}}' in t) = 0 and (v_vars ->> 'disclosure') <> '' then\n    v_res := v_res || E'\\n\\n' || case when v_esc then '<i>' || (v_vars ->> 'disclosure') || '</i>' else (v_vars ->> 'disclosure') end;\n  end if;\n  v_res := btrim(regexp_replace(v_res, E'\\n{3,}', E'\\n\\n', 'g'));\n  return v_res;\nend $$;\n\n-- ---------- Aprovação / rejeição ---------------------------------------------\ncreate or replace function public.approve_offer(\n  p_offer uuid, p_destinations uuid[], p_scheduled_for timestamptz default null\n) returns integer\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  o record; pr record; d record; c record;\n  v_count integer := 0; v_id uuid; v_code text; v_text text; v_viol text[]; v_key text;\n  v_base text := public.setting_text('shortlink_base', ''); v_dest uuid; v_ins integer; v_limit integer;\nbegin\n  perform public.require_operator();\n  select * into o from public.offers where id = p_offer for update;\n  if not found then raise exception 'Oferta inexistente'; end if;\n  if o.status not in ('needs_review', 'approved', 'scheduled') then\n    raise exception 'Oferta em estado % não pode ser aprovada', o.status;\n  end if;\n  if o.affiliate_url is null then raise exception 'Oferta sem link de afiliado'; end if;\n  select * into pr from public.products where id = o.product_id;\n  if not public.host_allowed(pr.platform, o.affiliate_url) then\n    raise exception 'Link de afiliado fora dos domínios permitidos';\n  end if;\n  if o.expires_at is not null and o.expires_at <= now() then raise exception 'Oferta vencida'; end if;\n  if o.availability = 'out_of_stock' then raise exception 'Oferta sem estoque'; end if;\n  if p_destinations is null or cardinality(p_destinations) = 0 then\n    raise exception 'Selecione ao menos um destino';\n  end if;\n  select * into c from public.connectors where platform = pr.platform;\n  if not o.is_simulated and (c.id is null or c.mode in ('disabled', 'paused_policy', 'error')) then\n    raise exception 'Conector de % indisponível (estado: %)', pr.platform, coalesce(c.mode, 'inexistente');\n  end if;\n\n  foreach v_dest in array p_destinations loop\n    select * into d from public.destinations where id = v_dest;\n    if not found then raise exception 'Destino inexistente'; end if;\n    if not d.enabled then raise exception 'Destino \"%\" está desabilitado', d.name; end if;\n    if cardinality(d.categories) > 0 and (pr.category is null or not (pr.category = any (d.categories))) then\n      raise exception 'Categoria da oferta não é aceita pelo destino \"%\"', d.name;\n    end if;\n\n    v_key := p_offer::text || ':' || v_dest::text || ':1';\n    if exists (select 1 from public.publications where idempotency_key = v_key) then continue; end if;\n\n    v_id := gen_random_uuid();\n    v_code := substr(md5(random()::text || clock_timestamp()::text || v_id::text), 1, 8);\n    v_text := public.render_offer_text(p_offer, v_dest, v_code);\n    v_viol := public.text_violations(v_text);\n    if cardinality(v_viol) > 0 then\n      raise exception 'Texto contém termos proibidos: %', array_to_string(v_viol, ', ');\n    end if;\n    v_limit := case when pr.image_url is not null then 1024 else 4096 end;\n    if d.channel = 'telegram' and length(v_text) > v_limit then\n      raise exception 'Texto excede o limite do Telegram (% de % caracteres)', length(v_text), v_limit;\n    end if;\n\n    insert into public.publications\n      (id, offer_id, destination_id, content_version, rendered_text, status, idempotency_key,\n       scheduled_for, next_attempt_at)\n    values (v_id, p_offer, v_dest, 1, v_text, 'pending', v_key,\n            coalesce(p_scheduled_for, now()), coalesce(p_scheduled_for, now()))\n    on conflict (idempotency_key) do nothing;\n    get diagnostics v_ins = row_count;\n    if v_ins = 1 then\n      if coalesce(c.use_short_link, true) and v_base <> '' then\n        insert into public.short_links (code, publication_id, target_url) values (v_code, v_id, o.affiliate_url);\n      end if;\n      v_count := v_count + 1;\n    end if;\n  end loop;\n\n  update public.offers\n     set status = 'scheduled', approved_by = coalesce(auth.uid(), approved_by), approved_at = now()\n   where id = p_offer;\n  perform public.log_audit('offer_approved', 'offer', p_offer::text,\n    jsonb_build_object('destinos', to_jsonb(p_destinations), 'publicacoes_criadas', v_count,\n                       'agendada_para', p_scheduled_for));\n  return v_count;\nend $$;\n\ncreate or replace function public.reject_offer(p_offer uuid, p_reason text) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_status text;\nbegin\n  perform public.require_operator();\n  if coalesce(btrim(p_reason), '') = '' then raise exception 'Informe o motivo da rejeição'; end if;\n  select status into v_status from public.offers where id = p_offer for update;\n  if not found then raise exception 'Oferta inexistente'; end if;\n  if v_status in ('published', 'rejected', 'expired') then\n    raise exception 'Oferta em estado % não pode ser rejeitada', v_status;\n  end if;\n  update public.offers set status = 'rejected', rejected_reason = btrim(p_reason) where id = p_offer;\n  update public.publications set status = 'cancelled', note = 'Oferta rejeitada'\n   where offer_id = p_offer and status in ('pending', 'retry_scheduled');\n  perform public.log_audit('offer_rejected', 'offer', p_offer::text, jsonb_build_object('motivo', btrim(p_reason)));\nend $$;\n\ncreate or replace function public.expire_offers() returns integer\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_ids uuid[];\nbegin\n  with ex as (\n    update public.offers set status = 'expired'\n     where expires_at is not null and expires_at <= now()\n       and status in ('needs_review', 'approved', 'scheduled')\n    returning id)\n  select coalesce(array_agg(id), '{}') into v_ids from ex;\n  update public.publications set status = 'cancelled', note = 'Oferta expirada'\n   where offer_id = any (v_ids) and status in ('pending', 'retry_scheduled');\n  return cardinality(v_ids);\nend $$;\n\n-- Painel: colar o link de afiliado obtido no programa oficial (nunca montar link por suposição).\ncreate or replace function public.set_offer_affiliate_url(p_offer uuid, p_url text) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_platform text; v_status text;\nbegin\n  perform public.require_operator();\n  select pr.platform, o.status into v_platform, v_status\n    from public.offers o join public.products pr on pr.id = o.product_id where o.id = p_offer for update of o;\n  if not found then raise exception 'Oferta inexistente'; end if;\n  if v_status not in ('needs_review', 'approved') then\n    raise exception 'Oferta em estado % não permite alterar o link', v_status;\n  end if;\n  if not public.host_allowed(v_platform, btrim(p_url)) then\n    raise exception 'Link fora dos domínios permitidos para % (confirme o domínio oficial e cadastre em Configurações)', v_platform;\n  end if;\n  update public.offers set affiliate_url = btrim(p_url) where id = p_offer;\n  perform public.score_offer(p_offer);\n  perform public.log_audit('offer_link_set', 'offer', p_offer::text, jsonb_build_object('host', public.url_host(p_url)));\nend $$;\n"},{"version":"003_publication_functions.sql","sql":"-- ============================================================================\n-- 003_publication_functions.sql — fila, entrega, idempotência e operação.\n-- Regra de ouro: a tentativa é gravada ANTES do envio; timeout ambíguo vira\n-- `unknown` e nunca é reenviado automaticamente.\n-- ============================================================================\n\n-- ---------- Pausa global e configurações ------------------------------------\ncreate or replace function public.set_paused(p_paused boolean, p_reason text default null) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_operator();\n  if not p_paused then perform public.require_admin(); end if;\n  insert into public.settings (key, value, updated_by)\n  values ('paused', to_jsonb(p_paused), auth.uid())\n  on conflict (key) do update set value = excluded.value, updated_by = excluded.updated_by, updated_at = now();\n  perform public.log_audit(case when p_paused then 'global_pause' else 'global_resume' end,\n    'settings', 'paused', jsonb_build_object('motivo', p_reason));\nend $$;\n\ncreate or replace function public.set_setting(p_key text, p_value jsonb) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_old jsonb;\nbegin\n  perform public.require_admin();\n  if p_key = 'paused' then raise exception 'Use set_paused para a pausa global'; end if;\n  if p_key = 'mode' and (p_value #>> '{}') not in ('simulation', 'review', 'auto') then\n    raise exception 'Modo inválido (use simulation, review ou auto)';\n  end if;\n  select value into v_old from public.settings where key = p_key;\n  insert into public.settings (key, value, updated_by) values (p_key, p_value, auth.uid())\n  on conflict (key) do update set value = excluded.value, updated_by = excluded.updated_by, updated_at = now();\n  perform public.log_audit('setting_changed', 'settings', p_key,\n    jsonb_build_object('de', v_old, 'para', p_value));\nend $$;\n\n-- ---------- Fila: reservar o próximo envio ------------------------------------\ncreate or replace function public.claim_next_publication(p_worker text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  r record; d record; v_mode text; v_now_local time;\n  v_hour integer; v_day integer; v_last timestamptz; v_quiet boolean;\n  v_lock integer := public.setting_int('claim_lock_seconds', 120);\n  v_tz text := public.setting_text('timezone', 'America/Sao_Paulo');\n  v_claimed public.publications;\nbegin\n  if public.setting_bool('paused', false) then return null; end if;\n  v_mode := public.setting_text('mode', 'simulation');\n  v_now_local := (now() at time zone v_tz)::time;\n\n  for r in\n    select p.id, p.destination_id\n      from public.publications p\n      join public.offers o on o.id = p.offer_id\n      join public.destinations dd on dd.id = p.destination_id\n     where p.status in ('pending', 'retry_scheduled')\n       and p.next_attempt_at <= now()\n       and dd.enabled\n       and (o.expires_at is null or o.expires_at > now())\n       and o.status in ('scheduled', 'approved')\n       and (o.is_simulated or v_mode in ('review', 'auto'))\n     order by p.next_attempt_at, p.created_at\n       for update of p skip locked\n  loop\n    -- Serializa a avaliação de limites por destino (evita estourar o limite sob concorrência).\n    if not pg_try_advisory_xact_lock(hashtextextended(r.destination_id::text, 7)) then continue; end if;\n\n    select * into d from public.destinations where id = r.destination_id;\n    if d.quiet_start is not null and d.quiet_end is not null then\n      v_quiet := case when d.quiet_start < d.quiet_end\n                      then v_now_local >= d.quiet_start and v_now_local < d.quiet_end\n                      else v_now_local >= d.quiet_start or v_now_local < d.quiet_end end;\n      if v_quiet then continue; end if;\n    end if;\n\n    select count(*) filter (where coalesce(sent_at, claimed_at) > now() - interval '1 hour'),\n           count(*) filter (where coalesce(sent_at, claimed_at) > now() - interval '24 hours'),\n           max(coalesce(sent_at, claimed_at))\n      into v_hour, v_day, v_last\n      from public.publications\n     where destination_id = r.destination_id and status in ('claimed', 'sent', 'unknown');\n    if v_hour >= d.max_per_hour or v_day >= d.max_per_day then continue; end if;\n    if v_last is not null and v_last > now() - make_interval(secs => d.min_interval_s) then continue; end if;\n\n    update public.publications\n       set status = 'claimed', attempt_count = attempt_count + 1, claimed_at = now(),\n           locked_by = p_worker, locked_until = now() + make_interval(secs => v_lock)\n     where id = r.id\n    returning * into v_claimed;\n\n    return (\n      select jsonb_build_object(\n        'publication_id', v_claimed.id, 'offer_id', v_claimed.offer_id,\n        'destination_id', v_claimed.destination_id, 'channel', d.channel,\n        'external_chat_id', d.external_id, 'rendered_text', v_claimed.rendered_text,\n        'idempotency_key', v_claimed.idempotency_key, 'attempt', v_claimed.attempt_count,\n        'is_simulated', o.is_simulated, 'image_url', pr.image_url, 'title', pr.title)\n      from public.offers o join public.products pr on pr.id = o.product_id\n      where o.id = v_claimed.offer_id);\n  end loop;\n  return null;\nend $$;\n\n-- ---------- Resultado do envio -------------------------------------------------\ncreate or replace function public.complete_publication(p_id uuid, p_external_message_id text default null)\nreturns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_offer uuid;\nbegin\n  update public.publications\n     set status = 'sent', sent_at = now(), external_message_id = p_external_message_id,\n         locked_by = null, locked_until = null, last_error_code = null\n   where id = p_id and status in ('claimed', 'unknown')\n  returning offer_id into v_offer;\n  if not found then raise exception 'Publicação % não está em estado de conclusão', p_id; end if;\n  update public.offers set status = 'published' where id = v_offer and status in ('scheduled', 'approved');\n  perform public.log_audit('publication_sent', 'publication', p_id::text,\n    jsonb_build_object('mensagem', p_external_message_id));\nend $$;\n\ncreate or replace function public.fail_publication(\n  p_id uuid, p_error_code text, p_permanent boolean default false, p_retry_in_seconds integer default null\n) returns text\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  v_attempts integer; v_max integer := public.setting_int('max_attempts', 5); v_status text; v_delay integer;\nbegin\n  select attempt_count into v_attempts from public.publications where id = p_id and status = 'claimed' for update;\n  if not found then raise exception 'Publicação % não está reservada', p_id; end if;\n  if p_permanent or v_attempts >= v_max then\n    v_status := 'failed_permanent';\n    update public.publications\n       set status = v_status, last_error_code = left(p_error_code, 120), locked_by = null, locked_until = null\n     where id = p_id;\n  else\n    v_status := 'retry_scheduled';\n    -- backoff exponencial com jitter de até 20 %, teto de 1 h\n    v_delay := coalesce(p_retry_in_seconds,\n      least(3600, (30 * power(2, v_attempts - 1) * (1 + random() * 0.2))::integer));\n    update public.publications\n       set status = v_status, last_error_code = left(p_error_code, 120), locked_by = null, locked_until = null,\n           next_attempt_at = now() + make_interval(secs => v_delay)\n     where id = p_id;\n  end if;\n  perform public.log_audit('publication_failed', 'publication', p_id::text,\n    jsonb_build_object('codigo', left(p_error_code, 120), 'status', v_status, 'tentativa', v_attempts));\n  return v_status;\nend $$;\n\n-- Resultado ambíguo (timeout, resposta perdida): NUNCA reenviar sozinho.\ncreate or replace function public.mark_publication_unknown(p_id uuid, p_note text default null) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  update public.publications\n     set status = 'unknown', note = left(p_note, 300), locked_by = null, locked_until = null\n   where id = p_id and status = 'claimed';\n  if not found then raise exception 'Publicação % não está reservada', p_id; end if;\n  perform public.log_audit('publication_unknown', 'publication', p_id::text, jsonb_build_object('nota', p_note));\nend $$;\n\n-- Recuperação após reinício de worker: reserva vencida vira `unknown`, nunca `pending`.\ncreate or replace function public.release_stale_claims() returns integer\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_n integer;\nbegin\n  with s as (\n    update public.publications\n       set status = 'unknown', note = 'Reserva expirou sem confirmação do worker',\n           locked_by = null, locked_until = null\n     where status = 'claimed' and locked_until < now()\n    returning id)\n  select count(*) into v_n from s;\n  if v_n > 0 then\n    perform public.log_audit('stale_claims_released', 'publication', null, jsonb_build_object('quantidade', v_n));\n  end if;\n  return v_n;\nend $$;\n\n-- ---------- Ações humanas sobre publicações ------------------------------------\ncreate or replace function public.resolve_unknown(\n  p_id uuid, p_resolution text, p_external_message_id text default null\n) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_offer uuid;\nbegin\n  perform public.require_operator();\n  if p_resolution not in ('sent', 'cancelled') then raise exception 'Resolução inválida'; end if;\n  update public.publications\n     set status = p_resolution,\n         sent_at = case when p_resolution = 'sent' then now() else sent_at end,\n         external_message_id = coalesce(p_external_message_id, external_message_id),\n         note = 'Reconciliado manualmente'\n   where id = p_id and status = 'unknown'\n  returning offer_id into v_offer;\n  if not found then raise exception 'Publicação não está em estado unknown'; end if;\n  if p_resolution = 'sent' then\n    update public.offers set status = 'published' where id = v_offer and status in ('scheduled', 'approved');\n  end if;\n  perform public.log_audit('unknown_resolved', 'publication', p_id::text, jsonb_build_object('resolucao', p_resolution));\nend $$;\n\ncreate or replace function public.cancel_publication(p_id uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_operator();\n  update public.publications set status = 'cancelled', note = 'Cancelada manualmente'\n   where id = p_id and status in ('pending', 'retry_scheduled');\n  if not found then raise exception 'Só é possível cancelar publicações pendentes ou em nova tentativa'; end if;\n  perform public.log_audit('publication_cancelled', 'publication', p_id::text);\nend $$;\n\ncreate or replace function public.retry_publication(p_id uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_operator();\n  update public.publications\n     set status = 'pending', next_attempt_at = now(), attempt_count = 0, last_error_code = null,\n         note = 'Reenfileirada manualmente'\n   where id = p_id and status = 'failed_permanent';\n  if not found then raise exception 'Só é possível reenfileirar publicações com falha permanente'; end if;\n  perform public.log_audit('publication_requeued', 'publication', p_id::text);\nend $$;\n\ncreate or replace function public.edit_publication_text(p_id uuid, p_text text) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_viol text[];\nbegin\n  perform public.require_operator();\n  v_viol := public.text_violations(p_text);\n  if cardinality(v_viol) > 0 then raise exception 'Texto contém termos proibidos: %', array_to_string(v_viol, ', '); end if;\n  if coalesce(btrim(p_text), '') = '' then raise exception 'Texto vazio'; end if;\n  update public.publications set rendered_text = p_text, note = 'Texto editado manualmente'\n   where id = p_id and status in ('pending', 'retry_scheduled');\n  if not found then raise exception 'Só é possível editar o texto de publicações ainda não enviadas'; end if;\n  perform public.log_audit('publication_text_edited', 'publication', p_id::text);\nend $$;\n\n-- ---------- Redirecionador ------------------------------------------------------\ncreate or replace function public.record_click(\n  p_code text, p_visitor_hash text default null, p_ua_family text default null, p_referrer_host text default null\n) returns text\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_target text;\nbegin\n  select target_url into v_target from public.short_links where code = p_code and not disabled;\n  if v_target is null then return null; end if;\n  insert into public.click_events (code, visitor_hash, ua_family, referrer_host)\n  values (p_code, left(p_visitor_hash, 64), left(p_ua_family, 40), left(p_referrer_host, 120));\n  return v_target;\nend $$;\n\n-- ---------- Saúde, coletas e testes de destino -----------------------------------\ncreate or replace function public.heartbeat(p_service text, p_status text default 'ok', p_details jsonb default '{}')\nreturns void\nlanguage sql security definer set search_path = public as $$\n  insert into public.heartbeats (service, last_seen, status, details)\n  values (p_service, now(), p_status, public.scrub(p_details))\n  on conflict (service) do update set last_seen = now(), status = excluded.status, details = excluded.details\n$$;\n\ncreate or replace function public.start_run(p_platform text) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_conn uuid; v_mode text; v_id uuid;\nbegin\n  select id, mode into v_conn, v_mode from public.connectors where platform = p_platform;\n  if v_conn is null then raise exception 'Conector % inexistente', p_platform; end if;\n  if v_mode in ('disabled', 'paused_policy', 'error') then\n    raise exception 'Conector % não pode coletar no estado %', p_platform, v_mode;\n  end if;\n  insert into public.runs (connector_id) values (v_conn) returning id into v_id;\n  return v_id;\nend $$;\n\ncreate or replace function public.finish_run(\n  p_run uuid, p_status text, p_seen integer, p_accepted integer, p_rejected integer, p_error text default null\n) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_conn uuid;\nbegin\n  update public.runs\n     set finished_at = now(), status = p_status, items_seen = p_seen, items_accepted = p_accepted,\n         items_rejected = p_rejected, error_summary = left(p_error, 500)\n   where id = p_run returning connector_id into v_conn;\n  if p_status = 'success' then\n    update public.connectors set last_success_at = now() where id = v_conn;\n  elsif p_status = 'error' then\n    update public.connectors set last_error_at = now(), last_error = left(p_error, 300) where id = v_conn;\n  end if;\nend $$;\n\ncreate or replace function public.request_destination_test(p_destination uuid) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_id uuid;\nbegin\n  perform public.require_operator();\n  if not exists (select 1 from public.destinations where id = p_destination) then\n    raise exception 'Destino inexistente';\n  end if;\n  insert into public.destination_tests (destination_id, requested_by) values (p_destination, auth.uid())\n  returning id into v_id;\n  perform public.log_audit('destination_test_requested', 'destination', p_destination::text);\n  return v_id;\nend $$;\n\ncreate or replace function public.claim_destination_test() returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare t record;\nbegin\n  select * into t from public.destination_tests where status = 'pending'\n   order by requested_at for update skip locked limit 1;\n  if not found then return null; end if;\n  update public.destination_tests set status = 'claimed' where id = t.id;\n  return (select jsonb_build_object('test_id', t.id, 'destination_id', d.id, 'channel', d.channel,\n                                    'external_chat_id', d.external_id, 'name', d.name)\n          from public.destinations d where d.id = t.destination_id);\nend $$;\n\ncreate or replace function public.complete_destination_test(p_test uuid, p_ok boolean, p_error text default null)\nreturns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_dest uuid;\nbegin\n  update public.destination_tests\n     set status = case when p_ok then 'ok' else 'failed' end, completed_at = now(), error = left(p_error, 300)\n   where id = p_test and status = 'claimed' returning destination_id into v_dest;\n  if not found then raise exception 'Teste não está em andamento'; end if;\n  if p_ok then update public.destinations set tested_at = now() where id = v_dest; end if;\n  perform public.log_audit('destination_test_done', 'destination', v_dest::text,\n    jsonb_build_object('ok', p_ok, 'erro', p_error));\nend $$;\n\n-- ---------- Usuários do painel ------------------------------------------------------\ncreate or replace function public.handle_new_user() returns trigger\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  insert into public.profiles (user_id, email, name)\n  values (new.id, coalesce(new.email, ''), coalesce(new.raw_user_meta_data ->> 'name', split_part(coalesce(new.email, ''), '@', 1)))\n  on conflict (user_id) do nothing;\n  return new;\nend $$;\n\ncreate or replace function public.set_profile(p_user uuid, p_role text, p_active boolean) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_admins integer;\nbegin\n  perform public.require_admin();\n  if p_role not in ('admin', 'operator', 'viewer') then raise exception 'Perfil inválido'; end if;\n  select count(*) into v_admins from public.profiles where role = 'admin' and active and user_id <> p_user;\n  if v_admins = 0 and not (p_role = 'admin' and p_active) then\n    raise exception 'Operação deixaria o sistema sem nenhum administrador ativo';\n  end if;\n  update public.profiles set role = p_role, active = p_active where user_id = p_user;\n  if not found then raise exception 'Usuário inexistente'; end if;\nend $$;\n\n-- Primeiro administrador: rode UMA vez no SQL Editor, com o e-mail já cadastrado.\ncreate or replace function public.bootstrap_admin(p_email text) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  if exists (select 1 from public.profiles where role = 'admin' and active) then\n    raise exception 'Já existe administrador ativo';\n  end if;\n  update public.profiles set role = 'admin', active = true where lower(email) = lower(p_email);\n  if not found then raise exception 'Cadastre-se no painel com esse e-mail antes de promovê-lo'; end if;\nend $$;\n"},{"version":"004_reporting.sql","sql":"-- ============================================================================\n-- 004_reporting.sql — leitura agregada para o painel (sempre exige membro ativo)\n-- ============================================================================\n\ncreate or replace function public.dashboard_summary() returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare\n  v_res jsonb; v_alerts jsonb := '[]'::jsonb;\n  v_unknown integer; v_failed integer; v_paused boolean; v_oldest numeric; v_enabled integer;\n  c record; h record;\nbegin\n  if not public.is_member() then raise exception 'Acesso negado' using errcode = '42501'; end if;\n  v_paused := public.setting_bool('paused', false);\n\n  select count(*) into v_unknown from public.publications where status = 'unknown';\n  select count(*) into v_failed from public.publications where status = 'failed_permanent';\n  select count(*) into v_enabled from public.destinations where enabled;\n  select extract(epoch from (now() - min(created_at))) / 60 into v_oldest\n    from public.offers where status = 'needs_review';\n\n  if v_paused then\n    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object('level', 'warning', 'code', 'paused',\n      'message', 'Publicação pausada globalmente: nada é enviado até você retomar.'));\n  end if;\n  if v_unknown > 0 then\n    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object('level', 'critical', 'code', 'unknown',\n      'message', v_unknown || ' envio(s) em estado unknown aguardando reconciliação manual.'));\n  end if;\n  if v_failed > 0 then\n    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object('level', 'warning', 'code', 'failed',\n      'message', v_failed || ' publicação(ões) com falha permanente.'));\n  end if;\n  if v_oldest is not null and v_oldest > 24 * 60 then\n    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object('level', 'warning', 'code', 'stale_review',\n      'message', 'Há ofertas aguardando revisão há mais de 24 h.'));\n  end if;\n  if v_enabled = 0 then\n    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object('level', 'info', 'code', 'no_destination',\n      'message', 'Nenhum destino habilitado. Cadastre e teste um destino para publicar.'));\n  end if;\n  for c in select * from public.connectors loop\n    if c.mode = 'paused_policy' then\n      v_alerts := v_alerts || jsonb_build_array(jsonb_build_object('level', 'critical', 'code', 'connector_paused',\n        'message', c.display_name || ' pausado por política: revise os termos antes de retomar.'));\n    elsif c.mode = 'error' then\n      v_alerts := v_alerts || jsonb_build_array(jsonb_build_object('level', 'critical', 'code', 'connector_error',\n        'message', c.display_name || ' em erro: ' || coalesce(c.last_error, 'sem detalhe')));\n    end if;\n    if c.mode <> 'disabled' and c.review_due_at is not null and c.review_due_at < now() then\n      v_alerts := v_alerts || jsonb_build_array(jsonb_build_object('level', 'warning', 'code', 'review_due',\n        'message', 'Revisão de termos de ' || c.display_name || ' vencida.'));\n    end if;\n  end loop;\n  for h in select * from public.heartbeats where last_seen < now() - interval '5 minutes' loop\n    v_alerts := v_alerts || jsonb_build_array(jsonb_build_object('level', 'critical', 'code', 'heartbeat',\n      'message', 'Serviço ' || h.service || ' sem sinal há mais de 5 minutos.'));\n  end loop;\n\n  select jsonb_build_object(\n    'paused', v_paused,\n    'mode', public.setting_text('mode', 'simulation'),\n    'offers', (select jsonb_build_object(\n        'needs_review', count(*) filter (where status = 'needs_review'),\n        'scheduled', count(*) filter (where status = 'scheduled'),\n        'created_24h', count(*) filter (where created_at > now() - interval '24 hours'),\n        'published_24h', count(*) filter (where status = 'published' and updated_at > now() - interval '24 hours'),\n        'rejected_24h', count(*) filter (where status = 'rejected' and updated_at > now() - interval '24 hours'))\n      from public.offers),\n    'publications', (select jsonb_build_object(\n        'pending', count(*) filter (where status in ('pending', 'retry_scheduled')),\n        'unknown', count(*) filter (where status = 'unknown'),\n        'failed', count(*) filter (where status = 'failed_permanent'),\n        'sent_24h', count(*) filter (where status = 'sent' and sent_at > now() - interval '24 hours'),\n        'sent_prev_24h', count(*) filter (where status = 'sent' and sent_at > now() - interval '48 hours'\n                                          and sent_at <= now() - interval '24 hours'))\n      from public.publications),\n    'clicks', (select jsonb_build_object(\n        'last_24h', count(*) filter (where clicked_at > now() - interval '24 hours'),\n        'prev_24h', count(*) filter (where clicked_at > now() - interval '48 hours'\n                                     and clicked_at <= now() - interval '24 hours'))\n      from public.click_events),\n    'approval_rate_7d', (select case when count(*) filter (where status in ('scheduled', 'published', 'rejected')) = 0\n        then null else round(100.0 * count(*) filter (where status in ('scheduled', 'published'))\n             / count(*) filter (where status in ('scheduled', 'published', 'rejected')), 1) end\n      from public.offers where created_at > now() - interval '7 days'),\n    'oldest_review_minutes', v_oldest,\n    'connectors', coalesce((select jsonb_agg(jsonb_build_object(\n        'platform', platform, 'display_name', display_name, 'mode', mode,\n        'review_due_at', review_due_at, 'last_success_at', last_success_at, 'last_error_at', last_error_at)\n        order by platform) from public.connectors), '[]'::jsonb),\n    'destinations', coalesce((select jsonb_agg(jsonb_build_object(\n        'id', d.id, 'name', d.name, 'channel', d.channel, 'enabled', d.enabled, 'max_per_day', d.max_per_day,\n        'sent_24h', (select count(*) from public.publications p\n                      where p.destination_id = d.id and p.status = 'sent' and p.sent_at > now() - interval '24 hours'))\n        order by d.name) from public.destinations d), '[]'::jsonb),\n    'heartbeats', coalesce((select jsonb_agg(jsonb_build_object(\n        'service', service, 'status', status, 'last_seen', last_seen,\n        'age_seconds', extract(epoch from (now() - last_seen))::integer) order by service)\n      from public.heartbeats), '[]'::jsonb),\n    'alerts', v_alerts\n  ) into v_res;\n  return v_res;\nend $$;\n\ncreate or replace function public.analytics_overview(p_days integer default 14) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare\n  v_tz text := public.setting_text('timezone', 'America/Sao_Paulo');\n  v_from timestamptz; v_days integer := greatest(1, least(coalesce(p_days, 14), 90)); v_res jsonb;\nbegin\n  if not public.is_member() then raise exception 'Acesso negado' using errcode = '42501'; end if;\n  v_from := date_trunc('day', now() at time zone v_tz) at time zone v_tz - make_interval(days => v_days - 1);\n\n  with days as (\n    select (generate_series(0, v_days - 1) * interval '1 day' + (v_from at time zone v_tz))::date as day\n  ), sent as (\n    select (sent_at at time zone v_tz)::date as day, count(*) n\n      from public.publications where status = 'sent' and sent_at >= v_from group by 1\n  ), clicks as (\n    select (clicked_at at time zone v_tz)::date as day, count(*) n\n      from public.click_events where clicked_at >= v_from group by 1\n  ), by_channel as (\n    select d.channel,\n           count(distinct p.id) filter (where p.status = 'sent' and p.sent_at >= v_from) as sent,\n           count(ce.id) filter (where ce.clicked_at >= v_from) as clicks\n      from public.destinations d\n      left join public.publications p on p.destination_id = d.id\n      left join public.short_links sl on sl.publication_id = p.id\n      left join public.click_events ce on ce.code = sl.code\n     group by d.channel\n  ), by_platform as (\n    select pr.platform, count(ce.id) as clicks, count(distinct p.id) filter (where p.status = 'sent') as sent\n      from public.click_events ce\n      join public.short_links sl on sl.code = ce.code\n      join public.publications p on p.id = sl.publication_id\n      join public.offers o on o.id = p.offer_id\n      join public.products pr on pr.id = o.product_id\n     where ce.clicked_at >= v_from group by pr.platform\n  ), by_category as (\n    select coalesce(pr.category, 'Sem categoria') as category, count(ce.id) as clicks\n      from public.click_events ce\n      join public.short_links sl on sl.code = ce.code\n      join public.publications p on p.id = sl.publication_id\n      join public.offers o on o.id = p.offer_id\n      join public.products pr on pr.id = o.product_id\n     where ce.clicked_at >= v_from group by 1\n  ), top as (\n    select o.id as offer_id, pr.title, pr.platform, o.current_price, count(ce.id) as clicks\n      from public.click_events ce\n      join public.short_links sl on sl.code = ce.code\n      join public.publications p on p.id = sl.publication_id\n      join public.offers o on o.id = p.offer_id\n      join public.products pr on pr.id = o.product_id\n     where ce.clicked_at >= v_from group by o.id, pr.title, pr.platform, o.current_price\n     order by clicks desc limit 10\n  )\n  select jsonb_build_object(\n    'days', v_days,\n    'series', (select jsonb_agg(jsonb_build_object('day', d.day, 'sent', coalesce(s.n, 0), 'clicks', coalesce(c.n, 0)) order by d.day)\n               from days d left join sent s on s.day = d.day left join clicks c on c.day = d.day),\n    'by_channel', coalesce((select jsonb_agg(to_jsonb(b)) from by_channel b), '[]'::jsonb),\n    'by_platform', coalesce((select jsonb_agg(to_jsonb(b)) from by_platform b), '[]'::jsonb),\n    'by_category', coalesce((select jsonb_agg(to_jsonb(b) order by b.clicks desc) from by_category b), '[]'::jsonb),\n    'top_offers', coalesce((select jsonb_agg(to_jsonb(t) order by t.clicks desc) from top t), '[]'::jsonb),\n    'funnel', jsonb_build_object(\n      'ingested', (select count(*) from public.offers where created_at >= v_from),\n      'approved', (select count(*) from public.offers where approved_at >= v_from),\n      'published', (select count(*) from public.publications where status = 'sent' and sent_at >= v_from),\n      'clicked', (select count(distinct sl.publication_id) from public.click_events ce\n                    join public.short_links sl on sl.code = ce.code where ce.clicked_at >= v_from))\n  ) into v_res;\n  return v_res;\nend $$;\n"},{"version":"005_security_and_seed.sql","sql":"-- ============================================================================\n-- 005_security_and_seed.sql — RLS, permissões, gatilhos de auditoria e padrões.\n-- ============================================================================\n\n-- ---------- Gatilhos ----------------------------------------------------------\ncreate trigger trg_auth_new_user after insert on auth.users\n  for each row execute function public.handle_new_user();\n\ncreate trigger trg_audit_destinations after insert or update or delete on public.destinations\n  for each row execute function public.audit_row_change();\ncreate trigger trg_audit_templates after insert or update or delete on public.templates\n  for each row execute function public.audit_row_change();\ncreate trigger trg_audit_connectors after insert or update or delete on public.connectors\n  for each row execute function public.audit_row_change();\ncreate trigger trg_audit_profiles after update on public.profiles\n  for each row execute function public.audit_row_change();\n\n-- Versão do template sobe a cada alteração do corpo.\ncreate or replace function public.bump_template_version() returns trigger\nlanguage plpgsql as $$\nbegin\n  if new.body is distinct from old.body then\n    new.version := old.version + 1;\n    new.updated_by := auth.uid();\n  end if;\n  return new;\nend $$;\ncreate trigger trg_templates_version before update on public.templates\n  for each row execute function public.bump_template_version();\n\n-- ---------- RLS ---------------------------------------------------------------\nalter table public.profiles           enable row level security;\nalter table public.connectors         enable row level security;\nalter table public.products           enable row level security;\nalter table public.price_observations enable row level security;\nalter table public.offers             enable row level security;\nalter table public.destinations       enable row level security;\nalter table public.destination_tests  enable row level security;\nalter table public.templates          enable row level security;\nalter table public.publications       enable row level security;\nalter table public.short_links        enable row level security;\nalter table public.click_events       enable row level security;\nalter table public.audit_events       enable row level security;\nalter table public.runs               enable row level security;\nalter table public.settings           enable row level security;\nalter table public.heartbeats         enable row level security;\n\n-- Leitura: qualquer membro ativo.\ncreate policy read_member on public.connectors         for select to authenticated using (public.is_member());\ncreate policy read_member on public.products           for select to authenticated using (public.is_member());\ncreate policy read_member on public.price_observations for select to authenticated using (public.is_member());\ncreate policy read_member on public.offers             for select to authenticated using (public.is_member());\ncreate policy read_member on public.destinations       for select to authenticated using (public.is_member());\ncreate policy read_member on public.destination_tests  for select to authenticated using (public.is_member());\ncreate policy read_member on public.templates          for select to authenticated using (public.is_member());\ncreate policy read_member on public.publications       for select to authenticated using (public.is_member());\ncreate policy read_member on public.short_links        for select to authenticated using (public.is_member());\ncreate policy read_member on public.click_events       for select to authenticated using (public.is_member());\ncreate policy read_member on public.audit_events       for select to authenticated using (public.is_member());\ncreate policy read_member on public.runs               for select to authenticated using (public.is_member());\ncreate policy read_member on public.settings           for select to authenticated using (public.is_member());\ncreate policy read_member on public.heartbeats         for select to authenticated using (public.is_member());\n\n-- Perfis: cada um vê o próprio; administrador vê todos (precisa para aprovar contas).\ncreate policy read_self_or_admin on public.profiles for select to authenticated\n  using (user_id = auth.uid() or public.is_admin());\n\n-- Escrita direta só do administrador, e só nas tabelas de configuração.\ncreate policy admin_write on public.destinations for all to authenticated\n  using (public.is_admin()) with check (public.is_admin());\ncreate policy admin_write on public.templates for all to authenticated\n  using (public.is_admin()) with check (public.is_admin());\ncreate policy admin_write on public.connectors for update to authenticated\n  using (public.is_admin()) with check (public.is_admin());\n\n-- ---------- Permissões ---------------------------------------------------------\nrevoke all on all tables in schema public from anon;\nrevoke all on all functions in schema public from public, anon;\n\ngrant select on all tables in schema public to authenticated;\ngrant insert, update, delete on public.destinations, public.templates to authenticated;\ngrant update on public.connectors to authenticated;\n\ngrant all on all tables in schema public to service_role;\ngrant usage, select on all sequences in schema public to service_role;\ngrant execute on all functions in schema public to service_role;\n\n-- Auxiliares de RLS e leitura\ngrant execute on function public.app_role(), public.is_admin(), public.can_operate(), public.is_member()\n  to authenticated;\n-- Painel (RBAC verificado dentro de cada função)\ngrant execute on function\n  public.set_paused(boolean, text), public.set_setting(text, jsonb), public.ingest_offer(jsonb),\n  public.render_offer_text(uuid, uuid, text), public.approve_offer(uuid, uuid[], timestamptz),\n  public.reject_offer(uuid, text), public.set_offer_affiliate_url(uuid, text), public.resolve_unknown(uuid, text, text),\n  public.cancel_publication(uuid), public.retry_publication(uuid), public.edit_publication_text(uuid, text),\n  public.request_destination_test(uuid), public.set_profile(uuid, text, boolean),\n  public.dashboard_summary(), public.analytics_overview(integer), public.text_violations(text)\n  to authenticated;\n-- Somente o dono do banco executa:\nrevoke all on function public.bootstrap_admin(text) from service_role;\n\n-- ---------- Padrões -------------------------------------------------------------\ninsert into public.settings (key, value) values\n  ('paused', 'false'),\n  ('mode', '\"simulation\"'),\n  ('timezone', '\"America/Sao_Paulo\"'),\n  ('auto_approve_enabled', 'false'),\n  ('auto_approve_threshold', '90'),\n  ('max_price_age_minutes', '720'),\n  ('dedupe_window_hours', '72'),\n  ('republish_drop_pct', '10'),\n  ('min_history_observations', '5'),\n  ('min_history_days', '3'),\n  ('max_attempts', '5'),\n  ('claim_lock_seconds', '120'),\n  ('review_interval_days', '30'),\n  ('retention_days_clicks', '180'),\n  ('retention_days_audit', '365'),\n  ('shortlink_base', '\"\"'),\n  ('affiliate_disclosure',\n   '\"Esta publicação contém link de afiliado; posso receber comissão por compras qualificadas, sem custo adicional para você. Preço e estoque podem mudar.\"'),\n  ('banned_terms',\n   '[\"garantido\",\"últimas unidades\",\"ultimas unidades\",\"corre\",\"corra\",\"menor preço da história\",\"menor preço da historia\",\"só hoje\",\"acaba hoje\",\"última chance\",\"ultima chance\",\"vai acabar\"]'),\n  ('allowed_domains',\n   '{\"mercadolivre\":[\"mercadolivre.com.br\"],\"shopee\":[\"shopee.com.br\"],\"amazon\":[\"amazon.com.br\"]}')\non conflict (key) do nothing;\n\ninsert into public.connectors (platform, display_name, mode) values\n  ('mercadolivre', 'Mercado Livre', 'disabled'),\n  ('shopee', 'Shopee', 'disabled'),\n  ('amazon', 'Amazon Brasil', 'disabled'),\n  ('network', 'Redes de afiliados', 'disabled')\non conflict (platform) do nothing;\n\ninsert into public.templates (channel, kind, name, body) values\n  ('telegram', 'offer', 'Oferta — Telegram (HTML)',\nE'<b>{{title}}</b>\\n\\n💰 {{price}}\\n{{previous_line}}\\n{{coupon_line}}\\n🕒 Preço visto em {{observed_at}}\\n\\n🛒 <a href=\"{{url}}\">Ver oferta</a>\\n\\n<i>{{disclosure}}</i>'),\n  ('whatsapp', 'offer', 'Oferta — WhatsApp',\nE'*{{title}}*\\n\\n💰 {{price}}\\n{{previous_line}}\\n{{coupon_line}}\\n🕒 Preço visto em {{observed_at}}\\n\\n🛒 {{url}}\\n\\n_{{disclosure}}_')\non conflict do nothing;\n"},{"version":"006_chats.sql","sql":"-- ============================================================================\n-- 006_chats.sql — Conversas e grupos (WhatsApp/Telegram): espelho para o painel\n-- O n8n alimenta (webhooks da Evolution API e do Telegram); o painel só lê e\n-- enfileira respostas manuais (outbox), que o worker envia respeitando a pausa.\n-- ============================================================================\n\ncreate table public.chats (\n  id                   uuid primary key default gen_random_uuid(),\n  channel              text not null check (channel in ('telegram', 'whatsapp')),\n  external_id          text not null,\n  kind                 text not null default 'group' check (kind in ('group', 'channel', 'private')),\n  title                text not null,\n  username             text,\n  description          text,\n  participant_count    integer check (participant_count is null or participant_count >= 0),\n  we_are_admin         boolean not null default false,\n  destination_id       uuid references public.destinations (id) on delete set null,\n  last_message_at      timestamptz,\n  last_message_preview text,\n  unread_count         integer not null default 0 check (unread_count >= 0),\n  archived             boolean not null default false,\n  muted                boolean not null default false,\n  metadata             jsonb not null default '{}',\n  created_at           timestamptz not null default now(),\n  updated_at           timestamptz not null default now(),\n  unique (channel, external_id)\n);\ncreate index chats_list_idx on public.chats (channel, archived, last_message_at desc nulls last);\ncreate trigger trg_chats_updated before update on public.chats\n  for each row execute function public.set_updated_at();\n\ncreate table public.chat_participants (\n  chat_id      uuid not null references public.chats (id) on delete cascade,\n  external_id  text not null,\n  display_name text,\n  role         text not null default 'member' check (role in ('owner', 'admin', 'member')),\n  joined_at    timestamptz,\n  primary key (chat_id, external_id)\n);\n\ncreate table public.chat_messages (\n  id                 uuid primary key default gen_random_uuid(),\n  chat_id            uuid not null references public.chats (id) on delete cascade,\n  direction          text not null check (direction in ('in', 'out')),\n  external_id        text,\n  sender_external_id text,\n  sender_name        text,\n  kind               text not null default 'text'\n                     check (kind in ('text', 'image', 'video', 'audio', 'document', 'sticker', 'system', 'offer')),\n  body               text not null default '',\n  reply_to           text,\n  publication_id     uuid references public.publications (id) on delete set null,\n  outbox_id          uuid,\n  sent_at            timestamptz not null default now(),\n  created_at         timestamptz not null default now()\n);\ncreate unique index chat_messages_ext_uidx on public.chat_messages (chat_id, external_id) where external_id is not null;\ncreate index chat_messages_chat_idx on public.chat_messages (chat_id, sent_at desc);\ncreate unique index chat_messages_pub_uidx on public.chat_messages (publication_id) where publication_id is not null;\n\ncreate table public.chat_outbox (\n  id                  uuid primary key default gen_random_uuid(),\n  chat_id             uuid not null references public.chats (id) on delete cascade,\n  body                text not null check (length(btrim(body)) > 0 and length(body) <= 4000),\n  status              text not null default 'pending'\n                      check (status in ('pending', 'claimed', 'sent', 'failed', 'cancelled')),\n  idempotency_key     text not null unique,\n  requested_by        uuid,\n  attempt_count       integer not null default 0,\n  locked_until        timestamptz,\n  external_message_id text,\n  last_error          text,\n  created_at          timestamptz not null default now(),\n  sent_at             timestamptz\n);\ncreate index chat_outbox_queue_idx on public.chat_outbox (status, created_at);\n\ninsert into public.settings (key, value) values ('retention_days_messages', '90') on conflict (key) do nothing;\n\n-- ---------------------------------------------------------------------------\n-- Funções do worker (service_role; auth.uid() é nulo)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.upsert_chat(p jsonb) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_id uuid; v_channel text := p ->> 'channel'; v_ext text := p ->> 'external_id'; v_dest uuid;\nbegin\n  if v_channel not in ('telegram', 'whatsapp') or coalesce(btrim(v_ext), '') = '' then\n    raise exception 'channel/external_id inválidos';\n  end if;\n  select id into v_dest from public.destinations where channel = v_channel and external_id = v_ext;\n  insert into public.chats (channel, external_id, kind, title, username, description, participant_count, we_are_admin, destination_id, metadata)\n  values (v_channel, v_ext, coalesce(p ->> 'kind', 'group'), left(coalesce(nullif(btrim(p ->> 'title'), ''), v_ext), 200),\n          p ->> 'username', left(p ->> 'description', 1000), (p ->> 'participant_count')::integer,\n          coalesce((p ->> 'we_are_admin')::boolean, false), v_dest, public.scrub(coalesce(p -> 'metadata', '{}'::jsonb)))\n  on conflict (channel, external_id) do update set\n    kind = coalesce(p ->> 'kind', chats.kind),\n    title = left(coalesce(nullif(btrim(p ->> 'title'), ''), chats.title), 200),\n    username = coalesce(p ->> 'username', chats.username),\n    description = coalesce(left(p ->> 'description', 1000), chats.description),\n    participant_count = coalesce((p ->> 'participant_count')::integer, chats.participant_count),\n    we_are_admin = coalesce((p ->> 'we_are_admin')::boolean, chats.we_are_admin),\n    destination_id = coalesce(chats.destination_id, v_dest)\n  returning id into v_id;\n  return v_id;\nend $$;\n\ncreate or replace function public.ingest_chat_message(p jsonb) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  v_chat uuid; v_msg uuid; v_ext text := nullif(p ->> 'external_id', '');\n  v_dir text := coalesce(p ->> 'direction', 'in'); v_body text := left(coalesce(p ->> 'body', ''), 4000);\n  v_kind text := coalesce(p ->> 'kind', 'text'); v_at timestamptz := coalesce((p ->> 'sent_at')::timestamptz, now());\nbegin\n  if v_dir not in ('in', 'out') then raise exception 'direction inválida'; end if;\n  v_chat := public.upsert_chat(p -> 'chat');\n  if v_ext is not null and exists (select 1 from public.chat_messages where chat_id = v_chat and external_id = v_ext) then\n    return jsonb_build_object('status', 'duplicate', 'chat_id', v_chat);\n  end if;\n  insert into public.chat_messages (chat_id, direction, external_id, sender_external_id, sender_name, kind, body, reply_to, sent_at)\n  values (v_chat, v_dir, v_ext, p ->> 'sender_external_id', left(p ->> 'sender_name', 120), v_kind, v_body, p ->> 'reply_to', v_at)\n  returning id into v_msg;\n  update public.chats set\n    last_message_at = greatest(coalesce(last_message_at, v_at), v_at),\n    last_message_preview = case when v_at >= coalesce(last_message_at, v_at) then left(regexp_replace(v_body, '\\s+', ' ', 'g'), 140) else last_message_preview end,\n    unread_count = case when v_dir = 'in' then unread_count + 1 else unread_count end\n  where id = v_chat;\n  return jsonb_build_object('status', 'created', 'chat_id', v_chat, 'message_id', v_msg);\nend $$;\n\ncreate or replace function public.sync_chat_participants(p_chat uuid, p jsonb) returns integer\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_n integer;\nbegin\n  delete from public.chat_participants where chat_id = p_chat;\n  insert into public.chat_participants (chat_id, external_id, display_name, role, joined_at)\n  select p_chat, x ->> 'external_id', left(x ->> 'display_name', 120), coalesce(x ->> 'role', 'member'), (x ->> 'joined_at')::timestamptz\n  from jsonb_array_elements(coalesce(p, '[]'::jsonb)) x\n  where coalesce(x ->> 'external_id', '') <> ''\n  on conflict do nothing;\n  get diagnostics v_n = row_count;\n  update public.chats set participant_count = greatest(v_n, 0) where id = p_chat;\n  return v_n;\nend $$;\n\n-- Mensagem que saiu pela fila de publicações aparece como \"oferta\" na conversa do destino.\ncreate or replace function public.mirror_publication_to_chat() returns trigger\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_dest record; v_chat uuid;\nbegin\n  if new.status = 'sent' and (tg_op = 'INSERT' or old.status is distinct from 'sent') then\n    select * into v_dest from public.destinations where id = new.destination_id;\n    insert into public.chats (channel, external_id, kind, title, destination_id)\n    values (v_dest.channel, v_dest.external_id, case when v_dest.channel = 'telegram' then 'channel' else 'group' end, v_dest.name, v_dest.id)\n    on conflict (channel, external_id) do update set destination_id = coalesce(chats.destination_id, excluded.destination_id)\n    returning id into v_chat;\n    insert into public.chat_messages (chat_id, direction, external_id, kind, body, publication_id, sender_name, sent_at)\n    values (v_chat, 'out', new.external_message_id, 'offer', new.rendered_text, new.id, 'Central de Promoções', coalesce(new.sent_at, now()))\n    on conflict do nothing;\n    update public.chats set last_message_at = coalesce(new.sent_at, now()),\n      last_message_preview = left(regexp_replace(new.rendered_text, '<[^>]+>|\\s+', ' ', 'g'), 140)\n    where id = v_chat;\n  end if;\n  return new;\nend $$;\ncreate trigger trg_publications_mirror after insert or update of status on public.publications\n  for each row execute function public.mirror_publication_to_chat();\n\ncreate or replace function public.claim_chat_outbox(p_worker text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v record;\nbegin\n  if public.setting_bool('paused', false) then return null; end if;\n  update public.chat_outbox set status = 'failed', last_error = 'reserva vencida: confirme no canal antes de reenviar'\n   where status = 'claimed' and locked_until < now();\n  select o.*, c.channel, c.external_id as chat_external_id into v\n    from public.chat_outbox o join public.chats c on c.id = o.chat_id\n   where o.status = 'pending' order by o.created_at for update of o skip locked limit 1;\n  if not found then return null; end if;\n  update public.chat_outbox set status = 'claimed', attempt_count = attempt_count + 1,\n         locked_until = now() + make_interval(secs => public.setting_int('claim_lock_seconds', 120))\n   where id = v.id;\n  return jsonb_build_object('outbox_id', v.id, 'chat_id', v.chat_id, 'channel', v.channel,\n                            'chat_external_id', v.chat_external_id, 'text', v.body, 'worker', p_worker);\nend $$;\n\ncreate or replace function public.complete_chat_outbox(p_id uuid, p_external_message_id text default null) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v record;\nbegin\n  update public.chat_outbox set status = 'sent', sent_at = now(), external_message_id = p_external_message_id, locked_until = null\n   where id = p_id and status = 'claimed' returning * into v;\n  if not found then raise exception 'Mensagem não está reservada'; end if;\n  insert into public.chat_messages (chat_id, direction, external_id, kind, body, outbox_id, sender_name)\n  values (v.chat_id, 'out', p_external_message_id, 'text', v.body, v.id, 'Painel') on conflict do nothing;\n  update public.chats set last_message_at = now(), last_message_preview = left(regexp_replace(v.body, '\\s+', ' ', 'g'), 140) where id = v.chat_id;\nend $$;\n\ncreate or replace function public.fail_chat_outbox(p_id uuid, p_error text) returns void\nlanguage sql security definer set search_path = public as $$\n  update public.chat_outbox set status = 'failed', last_error = left(p_error, 300), locked_until = null where id = p_id and status = 'claimed'\n$$;\n\ncreate or replace function public.purge_old_messages() returns integer\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_n integer;\nbegin\n  delete from public.chat_messages where publication_id is null\n    and sent_at < now() - make_interval(days => public.setting_int('retention_days_messages', 90));\n  get diagnostics v_n = row_count;\n  return v_n;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- Funções do painel (RBAC dentro de cada uma)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.mark_chat_read(p_chat uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  if auth.uid() is not null and not public.is_member() then raise exception 'Acesso negado' using errcode = '42501'; end if;\n  update public.chats set unread_count = 0 where id = p_chat and unread_count > 0;\nend $$;\n\ncreate or replace function public.set_chat_flags(p_chat uuid, p_archived boolean, p_muted boolean) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_operator();\n  update public.chats set archived = coalesce(p_archived, archived), muted = coalesce(p_muted, muted) where id = p_chat;\n  if not found then raise exception 'Conversa inexistente'; end if;\n  perform public.log_audit('chat_flags', 'chat', p_chat::text, jsonb_build_object('archived', p_archived, 'muted', p_muted));\nend $$;\n\ncreate or replace function public.link_chat_destination(p_chat uuid, p_destination uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_chat record; v_dest record;\nbegin\n  perform public.require_admin();\n  select * into v_chat from public.chats where id = p_chat;\n  if not found then raise exception 'Conversa inexistente'; end if;\n  if p_destination is not null then\n    select * into v_dest from public.destinations where id = p_destination;\n    if not found then raise exception 'Destino inexistente'; end if;\n    if v_dest.channel <> v_chat.channel then raise exception 'Destino de outro canal'; end if;\n  end if;\n  update public.chats set destination_id = p_destination where id = p_chat;\n  perform public.log_audit('chat_linked', 'chat', p_chat::text, jsonb_build_object('destination', p_destination));\nend $$;\n\ncreate or replace function public.queue_chat_message(p_chat uuid, p_text text, p_key text default null) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_chat record; v_id uuid; v_text text := btrim(coalesce(p_text, '')); v_viol text[]; v_limit integer;\nbegin\n  perform public.require_operator();\n  select * into v_chat from public.chats where id = p_chat;\n  if not found then raise exception 'Conversa inexistente'; end if;\n  if v_text = '' then raise exception 'Mensagem vazia'; end if;\n  v_limit := case when v_chat.channel = 'telegram' then 4096 else 4000 end;\n  if length(v_text) > v_limit then raise exception 'Mensagem maior que % caracteres', v_limit; end if;\n  v_viol := public.text_violations(v_text);\n  if array_length(v_viol, 1) > 0 then raise exception 'Texto contém termos proibidos: %', array_to_string(v_viol, ', '); end if;\n  if v_chat.kind = 'channel' and not v_chat.we_are_admin then raise exception 'Não somos administradores deste canal'; end if;\n  if (select count(*) from public.chat_outbox where chat_id = p_chat and status in ('pending', 'claimed')) >= 5 then\n    raise exception 'Há mensagens demais aguardando envio nesta conversa';\n  end if;\n  insert into public.chat_outbox (chat_id, body, idempotency_key, requested_by)\n  values (p_chat, v_text, coalesce(p_key, gen_random_uuid()::text), auth.uid())\n  on conflict (idempotency_key) do update set idempotency_key = excluded.idempotency_key\n  returning id into v_id;\n  perform public.log_audit('chat_message_queued', 'chat', p_chat::text, jsonb_build_object('outbox', v_id, 'chars', length(v_text)));\n  return v_id;\nend $$;\n\ncreate or replace function public.cancel_chat_outbox(p_id uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_operator();\n  update public.chat_outbox set status = 'cancelled' where id = p_id and status = 'pending';\n  if not found then raise exception 'Só é possível cancelar mensagens ainda na fila'; end if;\n  perform public.log_audit('chat_message_cancelled', 'chat', p_id::text);\nend $$;\n\ncreate or replace function public.channel_overview(p_channel text) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\nbegin\n  if not public.is_member() then raise exception 'Acesso negado' using errcode = '42501'; end if;\n  return jsonb_build_object(\n    'chats', (select count(*) from public.chats where channel = p_channel and not archived),\n    'groups', (select count(*) from public.chats where channel = p_channel and not archived and kind in ('group', 'channel')),\n    'participants', (select coalesce(sum(participant_count), 0) from public.chats where channel = p_channel and not archived),\n    'unread', (select coalesce(sum(unread_count), 0) from public.chats where channel = p_channel and not archived and not muted),\n    'messages_in_24h', (select count(*) from public.chat_messages m join public.chats c on c.id = m.chat_id\n                         where c.channel = p_channel and m.direction = 'in' and m.sent_at > now() - interval '24 hours'),\n    'messages_out_24h', (select count(*) from public.chat_messages m join public.chats c on c.id = m.chat_id\n                          where c.channel = p_channel and m.direction = 'out' and m.sent_at > now() - interval '24 hours'),\n    'outbox_pending', (select count(*) from public.chat_outbox o join public.chats c on c.id = o.chat_id\n                        where c.channel = p_channel and o.status in ('pending', 'claimed')),\n    'linked_destinations', (select count(*) from public.chats where channel = p_channel and destination_id is not null));\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- RLS e permissões\n-- ---------------------------------------------------------------------------\nalter table public.chats             enable row level security;\nalter table public.chat_participants enable row level security;\nalter table public.chat_messages     enable row level security;\nalter table public.chat_outbox       enable row level security;\ncreate policy read_member on public.chats             for select to authenticated using (public.is_member());\ncreate policy read_member on public.chat_participants for select to authenticated using (public.is_member());\ncreate policy read_member on public.chat_messages     for select to authenticated using (public.is_member());\ncreate policy read_member on public.chat_outbox       for select to authenticated using (public.is_member());\n\nrevoke all on public.chats, public.chat_participants, public.chat_messages, public.chat_outbox from anon;\ngrant select on public.chats, public.chat_participants, public.chat_messages, public.chat_outbox to authenticated;\ngrant all on public.chats, public.chat_participants, public.chat_messages, public.chat_outbox to service_role;\n\nrevoke all on function public.upsert_chat(jsonb), public.ingest_chat_message(jsonb), public.sync_chat_participants(uuid, jsonb),\n  public.claim_chat_outbox(text), public.complete_chat_outbox(uuid, text), public.fail_chat_outbox(uuid, text),\n  public.purge_old_messages(), public.mark_chat_read(uuid), public.set_chat_flags(uuid, boolean, boolean),\n  public.link_chat_destination(uuid, uuid), public.queue_chat_message(uuid, text, text), public.cancel_chat_outbox(uuid),\n  public.channel_overview(text), public.mirror_publication_to_chat() from public, anon;\ngrant execute on function public.upsert_chat(jsonb), public.ingest_chat_message(jsonb), public.sync_chat_participants(uuid, jsonb),\n  public.claim_chat_outbox(text), public.complete_chat_outbox(uuid, text), public.fail_chat_outbox(uuid, text),\n  public.purge_old_messages(), public.mark_chat_read(uuid), public.set_chat_flags(uuid, boolean, boolean),\n  public.link_chat_destination(uuid, uuid), public.queue_chat_message(uuid, text, text), public.cancel_chat_outbox(uuid),\n  public.channel_overview(text) to service_role;\ngrant execute on function public.mark_chat_read(uuid), public.set_chat_flags(uuid, boolean, boolean),\n  public.link_chat_destination(uuid, uuid), public.queue_chat_message(uuid, text, text), public.cancel_chat_outbox(uuid),\n  public.channel_overview(text) to authenticated;\n"},{"version":"007_categorias_grupos_conectores.sql","sql":"-- 007 — Categorias de produto por destino, descoberta/criação de grupos, config de conectores, histórico de templates\n-- Aplique depois de 006. Idempotente onde possível.\n\n-- ---------------------------------------------------------------------------\n-- 1. Taxonomia de categorias (fonte única de verdade)\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.product_categories (\n  slug     text primary key check (slug ~ '^[a-z0-9-]{2,30}$'),\n  label    text not null,\n  icon     text not null default 'tag',\n  sort     integer not null default 100,\n  keywords text[] not null default '{}'\n);\n\ninsert into public.product_categories (slug, label, icon, sort, keywords) values\n  ('eletronicos',  'Eletrônicos',               'smartphone', 10, '{eletronico,audio,fone,smartphone,celular,tv,camera,smartwatch,wearable,caixa de som}'),\n  ('informatica',  'Informática',               'laptop',     20, '{informatica,computador,notebook,periferico,teclado,mouse,monitor,impressora,ssd,roteador}'),\n  ('games',        'Games',                     'gamepad',    30, '{game,games,console,videogame,playstation,xbox,nintendo}'),\n  ('casa',         'Casa e decoração',          'home',       40, '{casa,decoracao,movel,moveis,iluminacao,jardim,limpeza,utilidades domesticas,cama mesa banho}'),\n  ('cozinha',      'Cozinha e eletrodomésticos','utensils',   50, '{cozinha,eletrodomestico,panela,airfryer,air fryer,cafeteira,liquidificador,geladeira}'),\n  ('automotivo',   'Carro e moto',              'car',        60, '{automotivo,carro,moto,veiculo,pneu,som automotivo,acessorio automotivo,capacete}'),\n  ('moda',         'Moda e acessórios',         'shirt',      70, '{moda,roupa,calcado,tenis,bolsa,relogio,acessorio,mochila}'),\n  ('beleza',       'Beleza e perfumaria',       'sparkles',   80, '{beleza,perfume,maquiagem,cabelo,skincare,barbear}'),\n  ('saude',        'Saúde e bem-estar',         'heart',      90, '{saude,vitamina,suplemento,bem estar,massageador}'),\n  ('esporte',      'Esporte e lazer',           'dumbbell',  100, '{esporte,fitness,academia,ciclismo,bicicleta,camping,lazer,pesca}'),\n  ('bebes',        'Bebês e crianças',          'baby',      110, '{bebe,bebes,infantil,crianca,maternidade}'),\n  ('brinquedos',   'Brinquedos',                'puzzle',    120, '{brinquedo,boneca,lego,jogo de tabuleiro}'),\n  ('ferramentas',  'Ferramentas e construção',  'wrench',    130, '{ferramenta,construcao,eletrica,obra,furadeira,parafusadeira}'),\n  ('pet',          'Pet',                       'paw',       140, '{pet,animal,cachorro,gato,racao}'),\n  ('mercado',      'Mercado e bebidas',         'cart',      150, '{supermercado,mercado,alimento,bebida,cafe}'),\n  ('livros',       'Livros e papelaria',        'book',      160, '{livro,papelaria,escritorio,caderno}'),\n  ('outros',       'Outros',                    'tag',       999, '{}')\non conflict (slug) do nothing;\n\ncreate or replace function public.category_norm(t text) returns text\nlanguage sql immutable as $$\n  select btrim(regexp_replace(translate(lower(coalesce(t, '')), 'áàâãäéèêëíìîïóòôõöúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn'), '[^a-z0-9]+', ' ', 'g'))\n$$;\n\n-- Devolve o slug da categoria para um texto livre ('Eletrônicos', 'Carro e moto', 'fone bluetooth'…).\n-- Texto vazio → null. Texto sem correspondência → 'outros'.\ncreate or replace function public.category_slug(t text) returns text\nlanguage plpgsql stable set search_path = public as $$\ndeclare n text := public.category_norm(t); v text;\nbegin\n  if n = '' then return null; end if;\n  select pc.slug into v from public.product_categories pc\n   where pc.slug <> 'outros' and (\n     n = public.category_norm(pc.label) or n = replace(pc.slug, '-', ' ')\n     or exists (select 1 from unnest(pc.keywords) k\n                where (' ' || n || ' ') ~ (' ' || public.category_norm(k) || 's? ')))\n   order by pc.sort limit 1;\n  return coalesce(v, 'outros');\nend $$;\n\n-- Destinos passam a guardar SLUGS. Converte o que já existia.\nupdate public.destinations d set categories = coalesce((\n  select array_agg(distinct s) from (select public.category_slug(c) s from unnest(d.categories) c) x where s is not null), '{}')\n where cardinality(categories) > 0;\n\ncreate or replace function public.validate_destination_categories() returns trigger\nlanguage plpgsql as $$\ndeclare c text;\nbegin\n  foreach c in array coalesce(new.categories, '{}') loop\n    if not exists (select 1 from public.product_categories where slug = c) then\n      raise exception 'Categoria desconhecida: %', c;\n    end if;\n  end loop;\n  return new;\nend $$;\ndrop trigger if exists trg_destinations_categories on public.destinations;\ncreate trigger trg_destinations_categories before insert or update of categories on public.destinations\n  for each row execute function public.validate_destination_categories();\n\n-- approve_offer agora compara por slug (uma oferta \"Casa\" entra em destino \"casa\", etc.)\ncreate or replace function public.approve_offer(\n  p_offer uuid, p_destinations uuid[], p_scheduled_for timestamptz default null\n) returns integer\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  o record; pr record; d record; c record;\n  v_count integer := 0; v_id uuid; v_code text; v_text text; v_viol text[]; v_key text;\n  v_base text := public.setting_text('shortlink_base', ''); v_dest uuid; v_ins integer; v_limit integer;\nbegin\n  perform public.require_operator();\n  select * into o from public.offers where id = p_offer for update;\n  if not found then raise exception 'Oferta inexistente'; end if;\n  if o.status not in ('needs_review', 'approved', 'scheduled') then\n    raise exception 'Oferta em estado % não pode ser aprovada', o.status;\n  end if;\n  if o.affiliate_url is null then raise exception 'Oferta sem link de afiliado'; end if;\n  select * into pr from public.products where id = o.product_id;\n  if not public.host_allowed(pr.platform, o.affiliate_url) then\n    raise exception 'Link de afiliado fora dos domínios permitidos';\n  end if;\n  if o.expires_at is not null and o.expires_at <= now() then raise exception 'Oferta vencida'; end if;\n  if o.availability = 'out_of_stock' then raise exception 'Oferta sem estoque'; end if;\n  if p_destinations is null or cardinality(p_destinations) = 0 then\n    raise exception 'Selecione ao menos um destino';\n  end if;\n  select * into c from public.connectors where platform = pr.platform;\n  if not o.is_simulated and (c.id is null or c.mode in ('disabled', 'paused_policy', 'error')) then\n    raise exception 'Conector de % indisponível (estado: %)', pr.platform, coalesce(c.mode, 'inexistente');\n  end if;\n\n  foreach v_dest in array p_destinations loop\n    select * into d from public.destinations where id = v_dest;\n    if not found then raise exception 'Destino inexistente'; end if;\n    if not d.enabled then raise exception 'Destino \"%\" está desabilitado', d.name; end if;\n    if cardinality(d.categories) > 0 and (public.category_slug(pr.category) is null or not (public.category_slug(pr.category) = any (d.categories))) then\n      raise exception 'Categoria da oferta não é aceita pelo destino \"%\"', d.name;\n    end if;\n\n    v_key := p_offer::text || ':' || v_dest::text || ':1';\n    if exists (select 1 from public.publications where idempotency_key = v_key) then continue; end if;\n\n    v_id := gen_random_uuid();\n    v_code := substr(md5(random()::text || clock_timestamp()::text || v_id::text), 1, 8);\n    v_text := public.render_offer_text(p_offer, v_dest, v_code);\n    v_viol := public.text_violations(v_text);\n    if cardinality(v_viol) > 0 then\n      raise exception 'Texto contém termos proibidos: %', array_to_string(v_viol, ', ');\n    end if;\n    v_limit := case when pr.image_url is not null then 1024 else 4096 end;\n    if d.channel = 'telegram' and length(v_text) > v_limit then\n      raise exception 'Texto excede o limite do Telegram (% de % caracteres)', length(v_text), v_limit;\n    end if;\n\n    insert into public.publications\n      (id, offer_id, destination_id, content_version, rendered_text, status, idempotency_key,\n       scheduled_for, next_attempt_at)\n    values (v_id, p_offer, v_dest, 1, v_text, 'pending', v_key,\n            coalesce(p_scheduled_for, now()), coalesce(p_scheduled_for, now()))\n    on conflict (idempotency_key) do nothing;\n    get diagnostics v_ins = row_count;\n    if v_ins = 1 then\n      if coalesce(c.use_short_link, true) and v_base <> '' then\n        insert into public.short_links (code, publication_id, target_url) values (v_code, v_id, o.affiliate_url);\n      end if;\n      v_count := v_count + 1;\n    end if;\n  end loop;\n\n  update public.offers\n     set status = 'scheduled', approved_by = coalesce(auth.uid(), approved_by), approved_at = now()\n   where id = p_offer;\n  perform public.log_audit('offer_approved', 'offer', p_offer::text,\n    jsonb_build_object('destinos', to_jsonb(p_destinations), 'publicacoes_criadas', v_count,\n                       'agendada_para', p_scheduled_for));\n  return v_count;\nend $$;\n\n\ncreate or replace function public.set_offer_category(p_offer uuid, p_slug text) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_label text; v_prod uuid; v_status text;\nbegin\n  perform public.require_operator();\n  select label into v_label from public.product_categories where slug = p_slug;\n  if v_label is null then raise exception 'Categoria desconhecida'; end if;\n  select product_id, status into v_prod, v_status from public.offers where id = p_offer for update;\n  if not found then raise exception 'Oferta inexistente'; end if;\n  if v_status in ('published', 'rejected', 'expired') then raise exception 'Oferta em estado % não pode mudar de categoria', v_status; end if;\n  update public.products set category = v_label where id = v_prod;\n  perform public.log_audit('offer_category_set', 'offer', p_offer::text, jsonb_build_object('categoria', p_slug));\nend $$;\n\ncreate or replace function public.reopen_offer(p_offer uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_operator();\n  update public.offers set status = 'needs_review', rejected_reason = null where id = p_offer and status = 'rejected';\n  if not found then raise exception 'Só é possível reabrir ofertas rejeitadas'; end if;\n  perform public.log_audit('offer_reopened', 'offer', p_offer::text);\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- 2. Tarefas de canal: buscar grupos, criar grupo, verificar chat\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.channel_jobs (\n  id              uuid primary key default gen_random_uuid(),\n  kind            text not null check (kind in ('refresh_groups', 'create_group', 'verify_chat')),\n  channel         text not null check (channel in ('telegram', 'whatsapp')),\n  payload         jsonb not null default '{}'::jsonb,\n  status          text not null default 'pending' check (status in ('pending', 'claimed', 'done', 'failed', 'cancelled')),\n  result          jsonb,\n  last_error      text,\n  idempotency_key text unique,\n  requested_by    uuid,\n  requested_at    timestamptz not null default now(),\n  claimed_at      timestamptz,\n  locked_until    timestamptz,\n  finished_at     timestamptz\n);\ncreate index if not exists channel_jobs_pending_idx on public.channel_jobs (requested_at) where status in ('pending', 'claimed');\n\ncreate or replace function public.request_group_refresh(p_channel text) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_id uuid;\nbegin\n  perform public.require_operator();\n  if p_channel not in ('telegram', 'whatsapp') then raise exception 'Canal inválido'; end if;\n  select id into v_id from public.channel_jobs\n   where kind = 'refresh_groups' and channel = p_channel and status in ('pending', 'claimed') order by requested_at desc limit 1;\n  if v_id is not null then return v_id; end if;\n  insert into public.channel_jobs (kind, channel, requested_by) values ('refresh_groups', p_channel, auth.uid()) returning id into v_id;\n  return v_id;\nend $$;\n\ncreate or replace function public.request_group_creation(p_channel text, p_name text, p_description text, p_participants jsonb, p_key text)\nreturns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_id uuid; v_name text := btrim(coalesce(p_name, '')); v_parts jsonb; v_viol text[]; v_max integer := public.setting_int('max_group_creations_per_day', 3);\nbegin\n  perform public.require_admin();\n  if p_channel <> 'whatsapp' then\n    raise exception 'O Telegram não permite que bots criem grupos ou canais. Crie no aplicativo, adicione o bot como administrador e use \"Buscar grupos\".';\n  end if;\n  if length(v_name) < 3 or length(v_name) > 100 then raise exception 'O nome do grupo precisa ter de 3 a 100 caracteres'; end if;\n  v_viol := public.text_violations(v_name || ' ' || coalesce(p_description, ''));\n  if cardinality(v_viol) > 0 then raise exception 'Nome/descrição contém termos proibidos: %', array_to_string(v_viol, ', '); end if;\n  if length(coalesce(p_description, '')) > 500 then raise exception 'Descrição longa demais (máx. 500)'; end if;\n  select coalesce(jsonb_agg(distinct d), '[]'::jsonb) into v_parts from (\n    select regexp_replace(x ->> 'external_id', '\\D', '', 'g') as d from jsonb_array_elements(coalesce(p_participants, '[]'::jsonb)) x) q\n   where d ~ '^\\d{10,15}$';\n  if jsonb_array_length(v_parts) < 1 then raise exception 'Selecione ao menos 1 participante com número válido (DDI+DDD+número)'; end if;\n  if jsonb_array_length(v_parts) > 256 then raise exception 'Máximo de 256 participantes na criação'; end if;\n  if coalesce(btrim(p_key), '') <> '' then\n    select id into v_id from public.channel_jobs where idempotency_key = p_key;\n    if v_id is not null then return v_id; end if;\n  end if;\n  if (select count(*) from public.channel_jobs where kind = 'create_group' and channel = p_channel\n        and status <> 'cancelled' and requested_at > now() - interval '24 hours') >= v_max then\n    raise exception 'Limite de % criações de grupo por dia atingido (proteção contra bloqueio do número)', v_max;\n  end if;\n  insert into public.channel_jobs (kind, channel, payload, idempotency_key, requested_by)\n  values ('create_group', p_channel, jsonb_build_object('name', v_name, 'description', nullif(btrim(coalesce(p_description, '')), ''), 'participants', v_parts),\n          nullif(btrim(p_key), ''), auth.uid()) returning id into v_id;\n  perform public.log_audit('group_creation_requested', 'channel_job', v_id::text, jsonb_build_object('nome', v_name, 'participantes', jsonb_array_length(v_parts)));\n  return v_id;\nend $$;\n\ncreate or replace function public.request_chat_verify(p_channel text, p_ref text) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_id uuid; v_ref text := btrim(coalesce(p_ref, ''));\nbegin\n  perform public.require_operator();\n  if p_channel <> 'telegram' then raise exception 'Verificação por referência só existe para o Telegram'; end if;\n  if v_ref !~ '^(@[A-Za-z0-9_]{5,32}|-?[0-9]{5,20})$' then raise exception 'Informe @usuario do canal/grupo ou o ID numérico (ex.: -1001234567890)'; end if;\n  insert into public.channel_jobs (kind, channel, payload, requested_by) values ('verify_chat', p_channel, jsonb_build_object('ref', v_ref), auth.uid()) returning id into v_id;\n  return v_id;\nend $$;\n\ncreate or replace function public.cancel_channel_job(p_id uuid) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_operator();\n  update public.channel_jobs set status = 'cancelled', finished_at = now() where id = p_id and status = 'pending';\n  if not found then raise exception 'Só é possível cancelar tarefas que ainda não começaram'; end if;\nend $$;\n\n-- Worker (n8n)\ncreate or replace function public.claim_channel_job(p_worker text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v record;\nbegin\n  -- reserva vencida: criação de grupo NUNCA repete (poderia duplicar); as demais voltam para a fila\n  update public.channel_jobs set status = 'failed', finished_at = now(), locked_until = null,\n         last_error = 'reserva vencida: confira no aplicativo se o grupo foi criado antes de tentar de novo'\n   where status = 'claimed' and locked_until < now() and kind = 'create_group';\n  update public.channel_jobs set status = 'pending', locked_until = null where status = 'claimed' and locked_until < now();\n  select * into v from public.channel_jobs\n   where status = 'pending' and (kind = 'refresh_groups' or not public.setting_bool('paused', false))\n   order by requested_at for update skip locked limit 1;\n  if not found then return null; end if;\n  update public.channel_jobs set status = 'claimed', claimed_at = now(), locked_until = now() + interval '180 seconds' where id = v.id;\n  return jsonb_build_object('id', v.id, 'kind', v.kind, 'channel', v.channel, 'payload', v.payload);\nend $$;\n\ncreate or replace function public.complete_channel_job(p_id uuid, p_result jsonb) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare j record; g jsonb; v_chat uuid; v_n integer := 0;\nbegin\n  select * into j from public.channel_jobs where id = p_id and status = 'claimed' for update;\n  if not found then raise exception 'Tarefa não está reservada'; end if;\n  if j.kind = 'refresh_groups' then\n    for g in select * from jsonb_array_elements(coalesce(p_result -> 'groups', '[]'::jsonb)) loop\n      perform public.upsert_chat(g || jsonb_build_object('channel', j.channel)); v_n := v_n + 1;\n    end loop;\n    update public.channel_jobs set result = jsonb_build_object('groups', v_n) where id = p_id;\n  elsif j.kind = 'create_group' then\n    if coalesce(p_result ->> 'external_id', '') = '' then raise exception 'Resultado sem external_id do grupo'; end if;\n    v_chat := public.upsert_chat(jsonb_build_object('channel', j.channel, 'external_id', p_result ->> 'external_id', 'kind', 'group',\n      'title', coalesce(p_result ->> 'title', j.payload ->> 'name'), 'description', j.payload ->> 'description',\n      'participant_count', jsonb_array_length(coalesce(p_result -> 'participants', '[]'::jsonb)), 'we_are_admin', true));\n    perform public.sync_chat_participants(v_chat, coalesce(p_result -> 'participants', '[]'::jsonb));\n    update public.channel_jobs set result = jsonb_build_object('chat_id', v_chat, 'external_id', p_result ->> 'external_id') where id = p_id;\n  else\n    v_chat := public.upsert_chat((p_result -> 'chat') || jsonb_build_object('channel', j.channel));\n    update public.channel_jobs set result = jsonb_build_object('chat_id', v_chat) where id = p_id;\n  end if;\n  update public.channel_jobs set status = 'done', finished_at = now(), locked_until = null where id = p_id;\nend $$;\n\ncreate or replace function public.fail_channel_job(p_id uuid, p_error text) returns void\nlanguage sql security definer set search_path = public as $$\n  update public.channel_jobs set status = 'failed', last_error = left(p_error, 300), finished_at = now(), locked_until = null\n   where id = p_id and status = 'claimed'\n$$;\n\n-- Leituras do painel\ncreate or replace function public.list_discovered_groups(p_channel text) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\nbegin\n  if not public.is_member() then raise exception 'Sem permissão'; end if;\n  return coalesce((select jsonb_agg(jsonb_build_object(\n      'chat_id', c.id, 'external_id', c.external_id, 'title', c.title, 'kind', c.kind, 'username', c.username,\n      'participant_count', c.participant_count, 'we_are_admin', c.we_are_admin,\n      'destination_id', d.id, 'destination_name', d.name) order by c.title)\n    from public.chats c left join public.destinations d on d.channel = c.channel and d.external_id = c.external_id\n   where c.channel = p_channel and c.kind in ('group', 'channel') and not c.archived), '[]'::jsonb);\nend $$;\n\ncreate or replace function public.list_contacts(p_channel text, p_q text default null) returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\nbegin\n  if not public.is_member() then raise exception 'Sem permissão'; end if;\n  return coalesce((select jsonb_agg(jsonb_build_object('external_id', x.eid, 'display_name', x.name) order by x.name) from (\n      select distinct on (eid) eid, name from (\n        select c.external_id as eid, c.title as name from public.chats c where c.channel = p_channel and c.kind = 'private'\n        union all\n        select cp.external_id, coalesce(cp.display_name, cp.external_id) from public.chat_participants cp join public.chats c on c.id = cp.chat_id\n         where c.channel = p_channel and cp.role <> 'owner') u\n      where coalesce(p_q, '') = '' or u.name ilike '%' || p_q || '%' or u.eid ilike '%' || p_q || '%'\n      order by eid, name) x limit 300), '[]'::jsonb);\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- 3. Configuração dos conectores (sem segredos!)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.validate_connector_config() returns trigger\nlanguage plpgsql as $$\ndeclare k text; v jsonb; n numeric;\nbegin\n  for k, v in select * from jsonb_each(coalesce(new.config, '{}'::jsonb)) loop\n    if k ~* '(secret|token|passw|senha|api_?key|authorization|bearer)' then\n      raise exception 'Não guarde segredos no painel (campo \"%\"). Guarde a credencial no n8n e informe só o nome dela em credential_ref.', k;\n    end if;\n    if jsonb_typeof(v) = 'string' and (v #>> '{}') ~ '^(sk-|eyJ|AKIA|xox[bp]-|ghp_)' then\n      raise exception 'O valor de \"%\" parece um segredo; não é permitido guardá-lo aqui', k;\n    end if;\n  end loop;\n  foreach k in array array['poll_minutes', 'min_discount_pct', 'min_score', 'max_items_per_run', 'max_price', 'min_price'] loop\n    if new.config ? k then\n      if jsonb_typeof(new.config -> k) <> 'number' then raise exception '\"%\" precisa ser número', k; end if;\n      n := (new.config ->> k)::numeric;\n      if k = 'poll_minutes' and (n < 5 or n > 1440) then raise exception 'poll_minutes deve ficar entre 5 e 1440'; end if;\n      if k = 'min_discount_pct' and (n < 0 or n > 95) then raise exception 'min_discount_pct deve ficar entre 0 e 95'; end if;\n      if k = 'min_score' and (n < 0 or n > 100) then raise exception 'min_score deve ficar entre 0 e 100'; end if;\n      if k = 'max_items_per_run' and (n < 1 or n > 500) then raise exception 'max_items_per_run deve ficar entre 1 e 500'; end if;\n      if k in ('max_price', 'min_price') and n < 0 then raise exception '% não pode ser negativo', k; end if;\n    end if;\n  end loop;\n  if new.config ? 'categories' then\n    if jsonb_typeof(new.config -> 'categories') <> 'array' then raise exception '\"categories\" precisa ser uma lista'; end if;\n    if exists (select 1 from jsonb_array_elements_text(new.config -> 'categories') s where s not in (select slug from public.product_categories)) then\n      raise exception 'Categoria desconhecida em \"categories\"';\n    end if;\n  end if;\n  return new;\nend $$;\ndrop trigger if exists trg_connectors_config on public.connectors;\ncreate trigger trg_connectors_config before insert or update of config on public.connectors\n  for each row execute function public.validate_connector_config();\n\n-- ---------------------------------------------------------------------------\n-- 4. Histórico de versões dos templates\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.template_versions (\n  id          uuid primary key default gen_random_uuid(),\n  template_id uuid not null references public.templates (id) on delete cascade,\n  version     integer not null,\n  body        text not null,\n  changed_by  uuid,\n  changed_at  timestamptz not null default now(),\n  unique (template_id, version)\n);\ninsert into public.template_versions (template_id, version, body) select id, version, body from public.templates on conflict do nothing;\ncreate or replace function public.log_template_version() returns trigger\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  if tg_op = 'INSERT' or new.body is distinct from old.body then\n    insert into public.template_versions (template_id, version, body, changed_by) values (new.id, new.version, new.body, auth.uid())\n    on conflict (template_id, version) do nothing;\n  end if;\n  return new;\nend $$;\ndrop trigger if exists trg_templates_history on public.templates;\ncreate trigger trg_templates_history after insert or update of body on public.templates\n  for each row execute function public.log_template_version();\n\n-- ---------------------------------------------------------------------------\n-- 5. Reagendar publicação\n-- ---------------------------------------------------------------------------\ncreate or replace function public.reschedule_publication(p_id uuid, p_when timestamptz) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_operator();\n  if p_when is null or p_when < now() - interval '1 minute' or p_when > now() + interval '30 days' then\n    raise exception 'Escolha um horário entre agora e 30 dias';\n  end if;\n  update public.publications set scheduled_for = greatest(p_when, now()), next_attempt_at = greatest(p_when, now()), note = 'Reagendada manualmente'\n   where id = p_id and status in ('pending', 'retry_scheduled');\n  if not found then raise exception 'Só é possível reagendar publicações pendentes ou em nova tentativa'; end if;\n  perform public.log_audit('publication_rescheduled', 'publication', p_id::text, jsonb_build_object('para', p_when));\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- RLS e permissões\n-- ---------------------------------------------------------------------------\nalter table public.product_categories enable row level security;\nalter table public.channel_jobs       enable row level security;\nalter table public.template_versions  enable row level security;\ncreate policy read_member on public.product_categories for select to authenticated using (public.is_member());\ncreate policy read_member on public.channel_jobs       for select to authenticated using (public.is_member());\ncreate policy read_member on public.template_versions for select to authenticated using (public.is_member());\nrevoke all on public.product_categories, public.channel_jobs, public.template_versions from anon;\ngrant select on public.product_categories, public.channel_jobs, public.template_versions to authenticated;\ngrant all on public.product_categories, public.channel_jobs, public.template_versions to service_role;\n\nrevoke all on function public.category_norm(text), public.category_slug(text), public.set_offer_category(uuid, text), public.reopen_offer(uuid),\n  public.request_group_refresh(text), public.request_group_creation(text, text, text, jsonb, text), public.request_chat_verify(text, text),\n  public.cancel_channel_job(uuid), public.claim_channel_job(text), public.complete_channel_job(uuid, jsonb), public.fail_channel_job(uuid, text),\n  public.list_discovered_groups(text), public.list_contacts(text, text), public.reschedule_publication(uuid, timestamptz),\n  public.approve_offer(uuid, uuid[], timestamptz) from public, anon;\ngrant execute on function public.category_norm(text), public.category_slug(text), public.claim_channel_job(text),\n  public.complete_channel_job(uuid, jsonb), public.fail_channel_job(uuid, text) to service_role;\ngrant execute on function public.category_slug(text), public.set_offer_category(uuid, text), public.reopen_offer(uuid),\n  public.request_group_refresh(text), public.request_group_creation(text, text, text, jsonb, text), public.request_chat_verify(text, text),\n  public.cancel_channel_job(uuid), public.list_discovered_groups(text), public.list_contacts(text, text),\n  public.reschedule_publication(uuid, timestamptz), public.approve_offer(uuid, uuid[], timestamptz) to authenticated;\ngrant execute on function public.approve_offer(uuid, uuid[], timestamptz) to service_role;\n"},{"version":"008_integracoes.sql","sql":"-- ============================================================================\n-- 008 — Integrações: Evolution API (WhatsApp), Telegram e APIs das plataformas\n--\n-- O painel NUNCA fala com a Evolution, o Telegram ou as lojas. Ele:\n--   * guarda a configuração (settings int_*), sem segredo;\n--   * guarda segredos em integration_secrets, só de ESCRITA (ninguém lê pelo painel;\n--     só o n8n, com service_role, lê);\n--   * pede ações (QR code, testar, verificar bot…) em channel_jobs (kind = 'integration');\n--   * lê o estado que o n8n devolve (settings int_status_*).\n-- ============================================================================\n\n-- ---------------------------------------------------------------------------\n-- 1. channel_jobs aceita ações de integração (sem canal)\n-- ---------------------------------------------------------------------------\nalter table public.channel_jobs drop constraint if exists channel_jobs_kind_check;\nalter table public.channel_jobs drop constraint if exists channel_jobs_channel_check;\nalter table public.channel_jobs alter column channel drop not null;\nalter table public.channel_jobs add constraint channel_jobs_kind_check\n  check (kind in ('refresh_groups', 'create_group', 'verify_chat', 'integration'));\nalter table public.channel_jobs add constraint channel_jobs_channel_check\n  check (channel is null or channel in ('telegram', 'whatsapp'));\n\n-- ---------------------------------------------------------------------------\n-- 2. Segredos (write-only)\n-- ---------------------------------------------------------------------------\ncreate table if not exists public.integration_secrets (\n  key        text primary key,\n  value      text not null,\n  hint       text not null,\n  updated_at timestamptz not null default now(),\n  updated_by uuid\n);\nalter table public.integration_secrets enable row level security;   -- sem policy: ninguém lê pela API\nrevoke all on public.integration_secrets from public, anon, authenticated;\ngrant all on public.integration_secrets to service_role;\n\ncreate or replace function public.integration_secret_keys() returns text[]\nlanguage sql immutable as $$\n  select array['evolution_api_key', 'telegram_bot_token', 'telegram_webhook_secret', 'ml_client_secret', 'shopee_secret', 'amazon_client_secret']\n$$;\n\ncreate or replace function public.set_integration_secret(p_key text, p_value text) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v text := btrim(coalesce(p_value, ''));\nbegin\n  perform public.require_admin();\n  if not (p_key = any (public.integration_secret_keys())) then raise exception 'Segredo desconhecido'; end if;\n  if v ~ '\\s' then raise exception 'O valor não pode ter espaços ou quebras de linha'; end if;\n  if p_key = 'telegram_bot_token' and v !~ '^\\d{6,12}:[A-Za-z0-9_-]{30,50}$' then\n    raise exception 'Token do bot inválido. O formato é 123456789:AAxxxxxxxx (copie do @BotFather)';\n  elsif p_key = 'telegram_webhook_secret' and v !~ '^[A-Za-z0-9_-]{16,256}$' then\n    raise exception 'O segredo do webhook usa só letras, números, - e _ (16 a 256 caracteres)';\n  elsif p_key = 'evolution_api_key' and length(v) not between 12 and 200 then\n    raise exception 'A chave da Evolution deve ter de 12 a 200 caracteres';\n  elsif p_key in ('ml_client_secret', 'shopee_secret', 'amazon_client_secret') and v !~ '^[A-Za-z0-9_.+=/-]{16,200}$' then\n    raise exception 'Chave secreta inválida (16 a 200 caracteres, sem espaços)';\n  end if;\n  insert into public.integration_secrets (key, value, hint, updated_by) values (p_key, v, right(v, 4), auth.uid())\n  on conflict (key) do update set value = excluded.value, hint = excluded.hint, updated_at = now(), updated_by = excluded.updated_by;\n  perform public.log_audit('integration_secret_set', 'integration', p_key, '{}'::jsonb);   -- nunca o valor\nend $$;\n\ncreate or replace function public.clear_integration_secret(p_key text) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  perform public.require_admin();\n  delete from public.integration_secrets where key = p_key;\n  perform public.log_audit('integration_secret_cleared', 'integration', p_key, '{}'::jsonb);\nend $$;\n\ncreate or replace function public.list_integration_secrets() returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\nbegin\n  if not public.is_member() then raise exception 'Sem permissão'; end if;\n  return coalesce((select jsonb_agg(jsonb_build_object('key', k, 'is_set', s.key is not null, 'hint', s.hint, 'updated_at', s.updated_at) order by k)\n    from unnest(public.integration_secret_keys()) k left join public.integration_secrets s on s.key = k), '[]'::jsonb);\nend $$;\n\n-- gera e guarda um segredo aleatório para o webhook do Telegram (o painel nunca o vê)\ncreate or replace function public.rotate_telegram_webhook_secret() returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');\nbegin\n  perform public.require_admin();\n  insert into public.integration_secrets (key, value, hint, updated_by) values ('telegram_webhook_secret', v, right(v, 4), auth.uid())\n  on conflict (key) do update set value = excluded.value, hint = excluded.hint, updated_at = now(), updated_by = excluded.updated_by;\n  perform public.log_audit('integration_secret_rotated', 'integration', 'telegram_webhook_secret', '{}'::jsonb);\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- 3. Configuração (sem segredo) e estado\n-- ---------------------------------------------------------------------------\ninsert into public.settings (key, value) values\n  ('int_evolution', '{\"base_url\":\"https://whatsapp.hubly.software\",\"instance\":\"\",\"webhook_url\":\"\",\"send_delay_min_s\":4,\"send_delay_max_s\":12,\"alert_numbers\":[],\"alerts\":true}'),\n  ('int_telegram',  '{\"enabled\":false,\"mode\":\"polling\",\"webhook_url\":\"\",\"admin_chat_id\":\"\",\"alerts\":true}'),\n  ('int_n8n',       '{\"base_url\":\"\"}')\non conflict (key) do nothing;\n\ncreate or replace function public.valid_https_url(p text) returns boolean\nlanguage sql immutable as $$\n  select p ~ '^https://[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?(:[0-9]{2,5})?(/[A-Za-z0-9._~%/-]*)?$'\n$$;\n\ncreate or replace function public.save_integration(p_provider text, p_config jsonb) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_old jsonb; v_new jsonb; k text; v jsonb; s text; n numeric; v_key text := 'int_' || p_provider;\nbegin\n  perform public.require_admin();\n  if p_provider not in ('evolution', 'telegram', 'n8n') then raise exception 'Integração desconhecida'; end if;\n  if jsonb_typeof(p_config) <> 'object' then raise exception 'Configuração inválida'; end if;\n  select value into v_old from public.settings where key = v_key;\n  v_new := coalesce(v_old, '{}'::jsonb);\n  for k, v in select * from jsonb_each(p_config) loop\n    if p_provider = 'evolution' then\n      if k = 'base_url' then\n        s := regexp_replace(btrim(v #>> '{}'), '/+$', '');\n        if not public.valid_https_url(s) then raise exception 'Endereço da Evolution inválido: use https://dominio (sem usuário, senha ou parâmetros)'; end if;\n        v := to_jsonb(s);\n      elsif k = 'instance' then\n        s := btrim(v #>> '{}');\n        if s <> '' and s !~ '^[A-Za-z0-9_-]{2,40}$' then raise exception 'Nome da instância: 2 a 40 letras, números, - ou _'; end if;\n        v := to_jsonb(s);\n      elsif k = 'webhook_url' then\n        s := btrim(v #>> '{}');\n        if s <> '' and not public.valid_https_url(s) then raise exception 'Endereço do webhook inválido (precisa ser https)'; end if;\n        v := to_jsonb(s);\n      elsif k in ('send_delay_min_s', 'send_delay_max_s') then\n        if jsonb_typeof(v) <> 'number' then raise exception '% precisa ser número', k; end if;\n        n := (v #>> '{}')::numeric;\n        if n < 1 or n > 120 then raise exception 'Intervalo de envio: entre 1 e 120 segundos'; end if;\n      elsif k = 'alerts' then\n        if jsonb_typeof(v) <> 'boolean' then raise exception '\"alerts\" precisa ser verdadeiro ou falso'; end if;\n      elsif k = 'alert_numbers' then\n        if jsonb_typeof(v) <> 'array' or jsonb_array_length(v) > 5 then raise exception 'Até 5 números para alertas'; end if;\n        if exists (select 1 from jsonb_array_elements_text(v) x where x !~ '^\\d{10,15}$') then raise exception 'Números de alerta: só dígitos com DDI e DDD (10 a 15)'; end if;\n      else raise exception 'Campo desconhecido: %', k;\n      end if;\n    elsif p_provider = 'telegram' then\n      if k = 'enabled' or k = 'alerts' then\n        if jsonb_typeof(v) <> 'boolean' then raise exception '\"%\" precisa ser verdadeiro ou falso', k; end if;\n      elsif k = 'mode' then\n        if (v #>> '{}') not in ('polling', 'webhook') then raise exception 'Modo deve ser polling ou webhook'; end if;\n      elsif k = 'webhook_url' then\n        s := btrim(v #>> '{}');\n        if s <> '' and not public.valid_https_url(s) then raise exception 'Endereço do webhook inválido (precisa ser https)'; end if;\n        v := to_jsonb(s);\n      elsif k = 'admin_chat_id' then\n        s := btrim(v #>> '{}');\n        if s <> '' and s !~ '^(-?\\d{5,20}|@[A-Za-z][A-Za-z0-9_]{4,31})$' then raise exception 'Chat do administrador: ID numérico ou @usuario'; end if;\n        v := to_jsonb(s);\n      else raise exception 'Campo desconhecido: %', k;\n      end if;\n    else\n      if k = 'base_url' then\n        s := regexp_replace(btrim(v #>> '{}'), '/+$', '');\n        if s <> '' and not public.valid_https_url(s) then raise exception 'Endereço do n8n inválido (https)'; end if;\n        v := to_jsonb(s);\n      else raise exception 'Campo desconhecido: %', k;\n      end if;\n    end if;\n    v_new := v_new || jsonb_build_object(k, v);\n  end loop;\n  if p_provider = 'evolution' and coalesce((v_new ->> 'send_delay_min_s')::numeric, 0) > coalesce((v_new ->> 'send_delay_max_s')::numeric, 999) then\n    raise exception 'O intervalo mínimo não pode ser maior que o máximo';\n  end if;\n  if p_provider = 'telegram' and v_new ->> 'mode' = 'webhook' and coalesce(v_new ->> 'webhook_url', '') = '' then\n    raise exception 'No modo webhook informe o endereço do webhook (https)';\n  end if;\n  insert into public.settings (key, value, updated_by) values (v_key, v_new, auth.uid())\n  on conflict (key) do update set value = excluded.value, updated_by = excluded.updated_by, updated_at = now();\n  perform public.log_audit('integration_saved', 'integration', p_provider, jsonb_build_object('campos', (select jsonb_agg(x) from jsonb_object_keys(p_config) x)));\nend $$;\n\n-- o n8n devolve o estado observado (instância, bot, API de loja). Nunca grava segredo aqui.\ncreate or replace function public.report_integration_status(p_provider text, p_status jsonb) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  if p_provider not in ('evolution', 'telegram', 'n8n', 'mercadolivre', 'shopee', 'amazon') then raise exception 'Integração desconhecida'; end if;\n  if jsonb_typeof(p_status) <> 'object' or length(p_status::text) > 8000 then raise exception 'Estado inválido ou grande demais'; end if;\n  insert into public.settings (key, value) values ('int_status_' || p_provider, p_status || jsonb_build_object('checked_at', now()))\n  on conflict (key) do update set value = excluded.value, updated_at = now();\nend $$;\n\n-- tudo o que o n8n precisa para trabalhar, numa chamada só (service_role)\ncreate or replace function public.get_integration_runtime() returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  select jsonb_build_object(\n    'evolution', coalesce((select value from public.settings where key = 'int_evolution'), '{}'::jsonb),\n    'telegram',  coalesce((select value from public.settings where key = 'int_telegram'),  '{}'::jsonb),\n    'n8n',       coalesce((select value from public.settings where key = 'int_n8n'),       '{}'::jsonb),\n    'paused',    public.setting_bool('paused', false),\n    'status',    coalesce((select jsonb_object_agg(substr(key, 12), value) from public.settings where key like 'int\\_status\\_%'), '{}'::jsonb),\n    'secrets',   coalesce((select jsonb_object_agg(key, value) from public.integration_secrets), '{}'::jsonb),\n    'connectors', coalesce((select jsonb_object_agg(platform, jsonb_build_object('mode', mode, 'config', config)) from public.connectors), '{}'::jsonb))\n$$;\n\n-- ---------------------------------------------------------------------------\n-- 4. Conectores: formato das credenciais de aplicativo (só o identificador; o segredo vai em integration_secrets)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.validate_connector_config() returns trigger\nlanguage plpgsql as $$\ndeclare k text; v jsonb; n numeric;\nbegin\n  for k, v in select * from jsonb_each(coalesce(new.config, '{}'::jsonb)) loop\n    if k ~* '(secret|token|passw|senha|api_?key|authorization|bearer)' then\n      raise exception 'Não guarde segredos aqui (campo \"%\"). Use o campo de chave secreta, que é só de escrita.', k;\n    end if;\n    if jsonb_typeof(v) = 'string' and (v #>> '{}') ~ '^(sk-|eyJ|AKIA|xox[bp]-|ghp_)' then\n      raise exception 'O valor de \"%\" parece um segredo; não é permitido guardá-lo aqui', k;\n    end if;\n  end loop;\n  foreach k in array array['poll_minutes', 'min_discount_pct', 'min_score', 'max_items_per_run', 'max_price', 'min_price'] loop\n    if new.config ? k then\n      if jsonb_typeof(new.config -> k) <> 'number' then raise exception '\"%\" precisa ser número', k; end if;\n      n := (new.config ->> k)::numeric;\n      if k = 'poll_minutes' and (n < 5 or n > 1440) then raise exception 'poll_minutes deve ficar entre 5 e 1440'; end if;\n      if k = 'min_discount_pct' and (n < 0 or n > 95) then raise exception 'min_discount_pct deve ficar entre 0 e 95'; end if;\n      if k = 'min_score' and (n < 0 or n > 100) then raise exception 'min_score deve ficar entre 0 e 100'; end if;\n      if k = 'max_items_per_run' and (n < 1 or n > 500) then raise exception 'max_items_per_run deve ficar entre 1 e 500'; end if;\n      if k in ('max_price', 'min_price') and n < 0 then raise exception '% não pode ser negativo', k; end if;\n    end if;\n  end loop;\n  foreach k in array array['app_id', 'client_id', 'partner_tag', 'affiliate_id', 'affiliate_tag'] loop\n    if new.config ? k and jsonb_typeof(new.config -> k) = 'string' and (new.config ->> k) !~ '^[A-Za-z0-9._:-]{2,120}$' then\n      raise exception '\"%\" deve ter de 2 a 120 caracteres (letras, números, ponto, - _ :), sem espaços', k;\n    end if;\n  end loop;\n  foreach k in array array['redirect_uri', 'api_endpoint'] loop\n    if new.config ? k and (new.config ->> k) <> '' and not public.valid_https_url(new.config ->> k) then\n      raise exception '\"%\" precisa ser um endereço https válido', k;\n    end if;\n  end loop;\n  if new.config ? 'marketplace' and (new.config ->> 'marketplace') !~ '^[A-Za-z0-9._-]{2,40}$' then\n    raise exception '\"marketplace\" inválido';\n  end if;\n  if new.config ? 'categories' then\n    if jsonb_typeof(new.config -> 'categories') <> 'array' then raise exception '\"categories\" precisa ser uma lista'; end if;\n    if exists (select 1 from jsonb_array_elements_text(new.config -> 'categories') s where s not in (select slug from public.product_categories)) then\n      raise exception 'Categoria desconhecida em \"categories\"';\n    end if;\n  end if;\n  return new;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- 5. Ações pedidas pelo painel (executadas pelo n8n)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.request_integration_action(p_provider text, p_action text, p_payload jsonb default '{}'::jsonb) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_id uuid; v_ok boolean; v_text text; v_payload jsonb := '{}'::jsonb; v_to text; v_ch text;\nbegin\n  perform public.require_admin();\n  v_ok := case p_provider\n    when 'evolution' then p_action in ('status', 'connect', 'restart', 'logout', 'set_webhook', 'create_instance', 'list_instances', 'send_test')\n    when 'telegram' then p_action in ('check', 'set_webhook', 'delete_webhook', 'send_test')\n    when 'mercadolivre' then p_action = 'check'\n    when 'shopee' then p_action = 'check'\n    when 'amazon' then p_action = 'check'\n    else false end;\n  if not coalesce(v_ok, false) then raise exception 'Ação não existe para esta integração'; end if;\n  v_ch := case p_provider when 'evolution' then 'whatsapp' when 'telegram' then 'telegram' else null end;\n\n  if p_action = 'send_test' then\n    if public.setting_bool('paused', false) then raise exception 'Envios pausados: retome antes de enviar o teste'; end if;\n    v_to := btrim(coalesce(p_payload ->> 'to', ''));\n    if p_provider = 'evolution' then\n      v_to := regexp_replace(v_to, '\\D', '', 'g');\n      if v_to !~ '^\\d{10,15}$' then raise exception 'Número inválido. Use DDI + DDD + número, só dígitos (ex.: 5511999990001)'; end if;\n    elsif v_to !~ '^(-?\\d{5,20}|@[A-Za-z][A-Za-z0-9_]{4,31})$' then raise exception 'Destino inválido: ID numérico do chat ou @canal';\n    end if;\n    v_text := left(btrim(coalesce(p_payload ->> 'text', 'Teste da Central de Promoções: a integração está funcionando.')), 500);\n    if array_length(public.text_violations(v_text), 1) > 0 then raise exception 'O texto contém termos proibidos'; end if;\n    v_payload := jsonb_build_object('to', v_to, 'text', v_text);\n  elsif p_provider = 'evolution' and p_action = 'connect' then\n    v_to := regexp_replace(coalesce(p_payload ->> 'pairing_number', ''), '\\D', '', 'g');\n    if v_to <> '' and v_to !~ '^\\d{10,15}$' then raise exception 'Número para código de pareamento inválido'; end if;\n    if v_to <> '' then v_payload := jsonb_build_object('pairing_number', v_to); end if;\n  end if;\n\n  -- repetição de clique: reaproveita a tarefa idêntica em andamento\n  select id into v_id from public.channel_jobs\n   where kind = 'integration' and status in ('pending', 'claimed') and payload ->> 'provider' = p_provider and payload ->> 'action' = p_action\n     and requested_at > now() - interval '60 seconds' limit 1;\n  if found then return v_id; end if;\n  if (select count(*) from public.channel_jobs where kind = 'integration' and requested_by = auth.uid() and requested_at > now() - interval '1 minute') >= 12 then\n    raise exception 'Muitas ações seguidas. Aguarde um minuto';\n  end if;\n  -- QR codes antigos não ficam guardados\n  update public.channel_jobs set result = null where kind = 'integration' and result ? 'qr' and finished_at < now() - interval '10 minutes';\n  insert into public.channel_jobs (kind, channel, payload, requested_by)\n  values ('integration', v_ch, jsonb_build_object('provider', p_provider, 'action', p_action) || v_payload, auth.uid()) returning id into v_id;\n  perform public.log_audit('integration_action', 'integration', p_provider || ':' || p_action, '{}'::jsonb);\n  return v_id;\nend $$;\n\n-- claim: ações de integração leem/diagnosticam e continuam mesmo com a pausa global; só o teste de envio é bloqueado\ncreate or replace function public.claim_channel_job(p_worker text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v record;\nbegin\n  -- reserva vencida: criação de grupo e teste de envio NUNCA repetem (poderiam duplicar)\n  update public.channel_jobs set status = 'failed', finished_at = now(), locked_until = null,\n         last_error = 'reserva vencida: confira no aplicativo se a ação foi concluída antes de tentar de novo'\n   where status = 'claimed' and locked_until < now() and (kind = 'create_group' or (kind = 'integration' and payload ->> 'action' = 'send_test'));\n  update public.channel_jobs set status = 'pending', locked_until = null where status = 'claimed' and locked_until < now();\n  select * into v from public.channel_jobs\n   where status = 'pending'\n     and (kind in ('refresh_groups', 'verify_chat') or (kind = 'integration' and payload ->> 'action' <> 'send_test')\n          or not public.setting_bool('paused', false))\n   order by requested_at for update skip locked limit 1;\n  if not found then return null; end if;\n  update public.channel_jobs set status = 'claimed', claimed_at = now(), locked_until = now() + interval '180 seconds' where id = v.id;\n  return jsonb_build_object('id', v.id, 'kind', v.kind, 'channel', v.channel, 'payload', v.payload);\nend $$;\n\ncreate or replace function public.complete_channel_job(p_id uuid, p_result jsonb) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare j record; g jsonb; v_chat uuid; v_n integer := 0;\nbegin\n  select * into j from public.channel_jobs where id = p_id and status = 'claimed' for update;\n  if not found then raise exception 'Tarefa não está reservada'; end if;\n  if j.kind = 'refresh_groups' then\n    for g in select * from jsonb_array_elements(coalesce(p_result -> 'groups', '[]'::jsonb)) loop\n      perform public.upsert_chat(g || jsonb_build_object('channel', j.channel)); v_n := v_n + 1;\n    end loop;\n    update public.channel_jobs set result = jsonb_build_object('groups', v_n) where id = p_id;\n  elsif j.kind = 'create_group' then\n    if coalesce(p_result ->> 'external_id', '') = '' then raise exception 'Resultado sem external_id do grupo'; end if;\n    v_chat := public.upsert_chat(jsonb_build_object('channel', j.channel, 'external_id', p_result ->> 'external_id', 'kind', 'group',\n      'title', coalesce(p_result ->> 'title', j.payload ->> 'name'), 'description', j.payload ->> 'description',\n      'participant_count', jsonb_array_length(coalesce(p_result -> 'participants', '[]'::jsonb)), 'we_are_admin', true));\n    perform public.sync_chat_participants(v_chat, coalesce(p_result -> 'participants', '[]'::jsonb));\n    update public.channel_jobs set result = jsonb_build_object('chat_id', v_chat, 'external_id', p_result ->> 'external_id') where id = p_id;\n  elsif j.kind = 'integration' then\n    if length(coalesce(p_result::text, '')) > 600000 then raise exception 'Resultado grande demais'; end if;\n    update public.channel_jobs set result = coalesce(p_result, '{}'::jsonb) where id = p_id;\n  else\n    v_chat := public.upsert_chat((p_result -> 'chat') || jsonb_build_object('channel', j.channel));\n    update public.channel_jobs set result = jsonb_build_object('chat_id', v_chat) where id = p_id;\n  end if;\n  update public.channel_jobs set status = 'done', finished_at = now(), locked_until = null where id = p_id;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- 6. Permissões\n-- ---------------------------------------------------------------------------\nrevoke all on function public.integration_secret_keys(), public.set_integration_secret(text, text), public.clear_integration_secret(text),\n  public.list_integration_secrets(), public.rotate_telegram_webhook_secret(), public.valid_https_url(text), public.save_integration(text, jsonb),\n  public.report_integration_status(text, jsonb), public.get_integration_runtime(), public.request_integration_action(text, text, jsonb) from public, anon;\ngrant execute on function public.set_integration_secret(text, text), public.clear_integration_secret(text), public.list_integration_secrets(),\n  public.rotate_telegram_webhook_secret(), public.save_integration(text, jsonb), public.request_integration_action(text, text, jsonb) to authenticated;\ngrant execute on function public.valid_https_url(text) to authenticated;\ngrant execute on function public.report_integration_status(text, jsonb), public.get_integration_runtime(), public.integration_secret_keys(),\n  public.valid_https_url(text) to service_role;\ngrant execute on function public.claim_channel_job(text), public.complete_channel_job(uuid, jsonb) to service_role;\n"},{"version":"009_grupos_acoes.sql","sql":"-- ============================================================================\n-- 009 — Gerenciamento de grupos (WhatsApp/Telegram) e padrões de criação de grupo\n--\n-- O painel nunca fala com a Evolution/Telegram: grava uma tarefa \"group_action\" e o n8n executa.\n--   * leituras (info, participantes, link de convite) funcionam mesmo com a pausa global;\n--   * alterações (nome, descrição, permissões, participantes, sair) respeitam a pausa;\n--   * alteração interrompida (reserva vencida) NUNCA é repetida sozinha: falha e pede conferência;\n--   * limites: 30 alterações / 10 min por usuário e 200 participantes adicionados / 24 h.\n-- ============================================================================\n\nalter table public.channel_jobs drop constraint if exists channel_jobs_kind_check;\nalter table public.channel_jobs add constraint channel_jobs_kind_check\n  check (kind in ('refresh_groups', 'create_group', 'verify_chat', 'integration', 'group_action'));\n\n-- ---------------------------------------------------------------------------\n-- Padrões aplicados a grupos novos\n-- ---------------------------------------------------------------------------\ninsert into public.settings (key, value) values\n  ('int_groups', '{\"whatsapp\":{\"only_admins_send\":true,\"lock_info\":true,\"ephemeral_seconds\":0,\"add_disclosure\":true,\"add_batch_size\":20,\"add_delay_s\":6,\"invite_after_create\":true},\"telegram\":{\"restrict_members_send\":false,\"add_disclosure\":true}}')\non conflict (key) do nothing;\n\ncreate or replace function public.save_group_defaults(p_config jsonb) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_old jsonb; v_new jsonb; ch text; k text; v jsonb; n numeric;\nbegin\n  perform public.require_admin();\n  if jsonb_typeof(p_config) <> 'object' then raise exception 'Configuração inválida'; end if;\n  select value into v_old from public.settings where key = 'int_groups';\n  v_new := coalesce(v_old, '{}'::jsonb);\n  for ch in select jsonb_object_keys(p_config) loop\n    if ch not in ('whatsapp', 'telegram') then raise exception 'Canal desconhecido: %', ch; end if;\n    if jsonb_typeof(p_config -> ch) <> 'object' then raise exception 'Configuração de % inválida', ch; end if;\n    v_new := v_new || jsonb_build_object(ch, coalesce(v_new -> ch, '{}'::jsonb));\n    for k, v in select * from jsonb_each(p_config -> ch) loop\n      if ch = 'whatsapp' and k in ('only_admins_send', 'lock_info', 'add_disclosure', 'invite_after_create') then\n        if jsonb_typeof(v) <> 'boolean' then raise exception '\"%\" precisa ser verdadeiro ou falso', k; end if;\n      elsif ch = 'whatsapp' and k = 'ephemeral_seconds' then\n        if jsonb_typeof(v) <> 'number' or (v #>> '{}')::numeric not in (0, 86400, 604800, 7776000) then raise exception 'Mensagens temporárias: desligado, 24 horas, 7 dias ou 90 dias'; end if;\n      elsif ch = 'whatsapp' and k = 'add_batch_size' then\n        if jsonb_typeof(v) <> 'number' then raise exception '\"%\" precisa ser número', k; end if;\n        n := (v #>> '{}')::numeric; if n < 1 or n > 50 or n <> trunc(n) then raise exception 'Participantes por lote: de 1 a 50'; end if;\n      elsif ch = 'whatsapp' and k = 'add_delay_s' then\n        if jsonb_typeof(v) <> 'number' then raise exception '\"%\" precisa ser número', k; end if;\n        n := (v #>> '{}')::numeric; if n < 2 or n > 60 then raise exception 'Espera entre lotes: de 2 a 60 segundos'; end if;\n      elsif ch = 'telegram' and k in ('restrict_members_send', 'add_disclosure') then\n        if jsonb_typeof(v) <> 'boolean' then raise exception '\"%\" precisa ser verdadeiro ou falso', k; end if;\n      else raise exception 'Campo desconhecido em %: %', ch, k;\n      end if;\n      v_new := jsonb_set(v_new, array[ch, k], v, true);\n    end loop;\n  end loop;\n  insert into public.settings (key, value) values ('int_groups', v_new) on conflict (key) do update set value = excluded.value, updated_at = now();\n  perform public.log_audit('group_defaults_saved', 'settings', 'int_groups', '{}'::jsonb);\nend $$;\n\n-- o worker lê os padrões junto com o resto da configuração\ncreate or replace function public.get_integration_runtime() returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  select jsonb_build_object(\n    'evolution', coalesce((select value from public.settings where key = 'int_evolution'), '{}'::jsonb),\n    'telegram',  coalesce((select value from public.settings where key = 'int_telegram'),  '{}'::jsonb),\n    'n8n',       coalesce((select value from public.settings where key = 'int_n8n'),       '{}'::jsonb),\n    'groups',    coalesce((select value from public.settings where key = 'int_groups'),    '{}'::jsonb),\n    'disclosure', coalesce((select value #>> '{}' from public.settings where key = 'affiliate_disclosure'), ''),\n    'paused',    public.setting_bool('paused', false),\n    'status',    coalesce((select jsonb_object_agg(substr(key, 12), value) from public.settings where key like 'int\\_status\\_%'), '{}'::jsonb),\n    'secrets',   coalesce((select jsonb_object_agg(key, value) from public.integration_secrets), '{}'::jsonb),\n    'connectors', coalesce((select jsonb_object_agg(platform, jsonb_build_object('mode', mode, 'config', config)) from public.connectors), '{}'::jsonb))\n$$;\n\n-- ---------------------------------------------------------------------------\n-- Pedido de ação em um grupo\n-- ---------------------------------------------------------------------------\ncreate or replace function public.group_action_is_read(p_action text) returns boolean\nlanguage sql immutable as $$ select p_action in ('info', 'participants', 'invite_code', 'admins') $$;\n\ncreate or replace function public.request_group_action(p_channel text, p_external_id text, p_action text, p_params jsonb default '{}'::jsonb) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare\n  v_id uuid; v_ext text := btrim(coalesce(p_external_id, '')); v_p jsonb := '{}'::jsonb; v_text text; v_nums jsonb; v_viol text[];\n  v_read boolean := public.group_action_is_read(p_action); v_ok boolean; v_adds integer; v_max integer; v_cap integer := public.setting_int('max_participant_adds_per_day', 200);\nbegin\n  perform public.require_admin();\n  if p_channel not in ('whatsapp', 'telegram') then raise exception 'Canal inválido'; end if;\n  if p_channel = 'whatsapp' and v_ext !~ '^\\d{5,25}(-\\d{5,20})?@g\\.us$' then raise exception 'Identificador de grupo do WhatsApp inválido'; end if;\n  if p_channel = 'telegram' and v_ext !~ '^(-?\\d{5,20}|@[A-Za-z][A-Za-z0-9_]{4,31})$' then raise exception 'Identificador do chat do Telegram inválido'; end if;\n  v_ok := case p_channel\n    when 'whatsapp' then p_action in ('info', 'participants', 'invite_code', 'revoke_invite', 'set_subject', 'set_description', 'set_only_admins_send', 'set_lock_info',\n                                      'set_ephemeral', 'add_participants', 'remove_participants', 'promote', 'demote', 'send_invite', 'leave', 'apply_defaults')\n    else p_action in ('info', 'admins', 'create_invite', 'revoke_invite', 'set_title', 'set_description', 'set_permissions', 'leave') end;\n  if not coalesce(v_ok, false) then raise exception 'Esta ação não existe para o %', case p_channel when 'whatsapp' then 'WhatsApp' else 'Telegram' end; end if;\n  if not v_read and public.setting_bool('paused', false) then raise exception 'Envios pausados: retome antes de alterar grupos'; end if;\n  p_params := coalesce(p_params, '{}'::jsonb);\n\n  if p_action in ('set_subject', 'set_title') then\n    v_text := btrim(coalesce(p_params ->> 'subject', ''));\n    if length(v_text) < 1 or length(v_text) > 100 then raise exception 'O nome precisa ter de 1 a 100 caracteres'; end if;\n    v_viol := public.text_violations(v_text);\n    if cardinality(v_viol) > 0 then raise exception 'O nome contém termos proibidos: %', array_to_string(v_viol, ', '); end if;\n    v_p := jsonb_build_object('subject', v_text);\n  elsif p_action = 'set_description' then\n    v_text := btrim(coalesce(p_params ->> 'description', ''));\n    v_max := (case p_channel when 'telegram' then 255 else 2048 end);\n    if length(v_text) > v_max then raise exception 'Descrição longa demais (máx. % caracteres)', v_max; end if;\n    v_viol := public.text_violations(v_text);\n    if cardinality(v_viol) > 0 then raise exception 'A descrição contém termos proibidos: %', array_to_string(v_viol, ', '); end if;\n    v_p := jsonb_build_object('description', v_text);\n  elsif p_action in ('set_only_admins_send', 'set_lock_info') then\n    if jsonb_typeof(p_params -> 'value') <> 'boolean' then raise exception 'Informe verdadeiro ou falso'; end if;\n    v_p := jsonb_build_object('value', p_params -> 'value');\n  elsif p_action = 'set_permissions' then\n    if jsonb_typeof(p_params -> 'can_send_messages') <> 'boolean' then raise exception 'Informe verdadeiro ou falso'; end if;\n    v_p := jsonb_build_object('can_send_messages', p_params -> 'can_send_messages');\n  elsif p_action = 'set_ephemeral' then\n    if jsonb_typeof(p_params -> 'seconds') <> 'number' or (p_params ->> 'seconds')::numeric not in (0, 86400, 604800, 7776000) then raise exception 'Mensagens temporárias: desligado, 24 horas, 7 dias ou 90 dias'; end if;\n    v_p := jsonb_build_object('seconds', (p_params ->> 'seconds')::integer);\n  elsif p_action in ('add_participants', 'remove_participants', 'promote', 'demote', 'send_invite') then\n    select coalesce(jsonb_agg(distinct d), '[]'::jsonb) into v_nums from (\n      select regexp_replace(x, '\\D', '', 'g') as d from jsonb_array_elements_text(coalesce(p_params -> 'numbers', '[]'::jsonb)) x) q where d ~ '^\\d{10,15}$';\n    if jsonb_array_length(v_nums) < 1 then raise exception 'Informe ao menos 1 número válido (DDI+DDD+número)'; end if;\n    if jsonb_array_length(v_nums) > 50 then raise exception 'No máximo 50 números por vez'; end if;\n    if p_action = 'add_participants' then\n      select coalesce(sum(jsonb_array_length(payload -> 'params' -> 'numbers')), 0) into v_adds from public.channel_jobs\n       where kind = 'group_action' and payload ->> 'action' = 'add_participants' and status <> 'cancelled' and requested_at > now() - interval '24 hours';\n      if v_adds + jsonb_array_length(v_nums) > v_cap then raise exception 'Limite de % participantes adicionados em 24 horas (proteção contra bloqueio do número). Já pedidos: %', v_cap, v_adds; end if;\n    end if;\n    v_p := jsonb_build_object('numbers', v_nums);\n    if p_action = 'send_invite' then v_p := v_p || jsonb_build_object('text', left(btrim(coalesce(p_params ->> 'text', '')), 300)); end if;\n  elsif p_action = 'revoke_invite' and p_channel = 'telegram' then\n    v_text := btrim(coalesce(p_params ->> 'link', ''));\n    if v_text !~ '^https://t\\.me/[A-Za-z0-9_+/-]{4,100}$' then raise exception 'Link de convite do Telegram inválido'; end if;\n    v_p := jsonb_build_object('link', v_text);\n  elsif p_action = 'leave' then\n    if (p_params ->> 'confirm') is distinct from 'true' then raise exception 'Confirme que o sistema deve sair deste grupo'; end if;\n    v_p := jsonb_build_object('confirm', true);\n  end if;\n\n  if not v_read then\n    if (select count(*) from public.channel_jobs where kind = 'group_action' and requested_by = auth.uid() and not public.group_action_is_read(payload ->> 'action')\n          and requested_at > now() - interval '10 minutes') >= 30 then\n      raise exception 'Muitas alterações seguidas. Aguarde alguns minutos';\n    end if;\n  end if;\n  -- clique repetido: reaproveita a tarefa idêntica em andamento\n  select id into v_id from public.channel_jobs\n   where kind = 'group_action' and channel = p_channel and status in ('pending', 'claimed') and requested_at > now() - interval '60 seconds'\n     and payload = jsonb_build_object('external_id', v_ext, 'action', p_action, 'params', v_p) limit 1;\n  if found then return v_id; end if;\n  -- links de convite antigos não ficam guardados\n  update public.channel_jobs set result = result - 'invite_url' where kind in ('group_action', 'create_group') and result ? 'invite_url' and finished_at < now() - interval '1 day';\n  insert into public.channel_jobs (kind, channel, payload, requested_by)\n  values ('group_action', p_channel, jsonb_build_object('external_id', v_ext, 'action', p_action, 'params', v_p), auth.uid()) returning id into v_id;\n  if not v_read then perform public.log_audit('group_action_requested', 'channel_job', v_id::text, jsonb_build_object('canal', p_channel, 'acao', p_action, 'grupo', v_ext)); end if;\n  return v_id;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- claim / complete\n-- ---------------------------------------------------------------------------\ncreate or replace function public.claim_channel_job(p_worker text) returns jsonb\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v record;\nbegin\n  -- reserva vencida: ações que alteram algo NUNCA repetem (poderiam duplicar ou desfazer)\n  update public.channel_jobs set status = 'failed', finished_at = now(), locked_until = null,\n         last_error = 'reserva vencida: confira no aplicativo se a ação foi concluída antes de tentar de novo'\n   where status = 'claimed' and locked_until < now()\n     and (kind = 'create_group' or (kind = 'integration' and payload ->> 'action' = 'send_test')\n          or (kind = 'group_action' and not public.group_action_is_read(payload ->> 'action')));\n  update public.channel_jobs set status = 'pending', locked_until = null where status = 'claimed' and locked_until < now();\n  select * into v from public.channel_jobs\n   where status = 'pending'\n     and (kind in ('refresh_groups', 'verify_chat') or (kind = 'integration' and payload ->> 'action' <> 'send_test')\n          or (kind = 'group_action' and public.group_action_is_read(payload ->> 'action'))\n          or not public.setting_bool('paused', false))\n   order by requested_at for update skip locked limit 1;\n  if not found then return null; end if;\n  update public.channel_jobs set status = 'claimed', claimed_at = now(), locked_until = now() + interval '240 seconds' where id = v.id;\n  return jsonb_build_object('id', v.id, 'kind', v.kind, 'channel', v.channel, 'payload', v.payload);\nend $$;\n\ncreate or replace function public.complete_channel_job(p_id uuid, p_result jsonb) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare j record; g jsonb; v_chat uuid; v_n integer := 0; v_res jsonb;\nbegin\n  select * into j from public.channel_jobs where id = p_id and status = 'claimed' for update;\n  if not found then raise exception 'Tarefa não está reservada'; end if;\n  if j.kind = 'refresh_groups' then\n    for g in select * from jsonb_array_elements(coalesce(p_result -> 'groups', '[]'::jsonb)) loop\n      perform public.upsert_chat(g || jsonb_build_object('channel', j.channel)); v_n := v_n + 1;\n    end loop;\n    update public.channel_jobs set result = jsonb_build_object('groups', v_n) where id = p_id;\n  elsif j.kind = 'create_group' then\n    if coalesce(p_result ->> 'external_id', '') = '' then raise exception 'Resultado sem external_id do grupo'; end if;\n    v_chat := public.upsert_chat(jsonb_build_object('channel', j.channel, 'external_id', p_result ->> 'external_id', 'kind', 'group',\n      'title', coalesce(p_result ->> 'title', j.payload ->> 'name'), 'description', j.payload ->> 'description',\n      'participant_count', jsonb_array_length(coalesce(p_result -> 'participants', '[]'::jsonb)), 'we_are_admin', true));\n    perform public.sync_chat_participants(v_chat, coalesce(p_result -> 'participants', '[]'::jsonb));\n    update public.channel_jobs set result = jsonb_strip_nulls(jsonb_build_object('chat_id', v_chat, 'external_id', p_result ->> 'external_id',\n      'invite_url', p_result ->> 'invite_url', 'applied', p_result -> 'applied', 'pending_numbers', p_result -> 'pending_numbers')) where id = p_id;\n  elsif j.kind = 'integration' then\n    if length(coalesce(p_result::text, '')) > 600000 then raise exception 'Resultado grande demais'; end if;\n    update public.channel_jobs set result = coalesce(p_result, '{}'::jsonb) where id = p_id;\n  elsif j.kind = 'group_action' then\n    if length(coalesce(p_result::text, '')) > 600000 then raise exception 'Resultado grande demais'; end if;\n    v_res := coalesce(p_result, '{}'::jsonb) - 'chat';\n    if p_result ? 'chat' and coalesce(p_result -> 'chat' ->> 'external_id', '') <> '' then\n      v_chat := public.upsert_chat((p_result -> 'chat') || jsonb_build_object('channel', j.channel));\n      v_res := v_res || jsonb_build_object('chat_id', v_chat);\n      if jsonb_typeof(p_result -> 'participants') = 'array' then perform public.sync_chat_participants(v_chat, p_result -> 'participants'); end if;\n    end if;\n    if p_result ->> 'left' = 'true' then\n      update public.chats set archived = true, we_are_admin = false where channel = j.channel and external_id = j.payload ->> 'external_id';\n    end if;\n    update public.channel_jobs set result = v_res where id = p_id;\n  else\n    v_chat := public.upsert_chat((p_result -> 'chat') || jsonb_build_object('channel', j.channel));\n    update public.channel_jobs set result = jsonb_build_object('chat_id', v_chat) where id = p_id;\n  end if;\n  update public.channel_jobs set status = 'done', finished_at = now(), locked_until = null where id = p_id;\nend $$;\n\n-- ---------------------------------------------------------------------------\n-- Permissões\n-- ---------------------------------------------------------------------------\nrevoke all on function public.save_group_defaults(jsonb), public.group_action_is_read(text), public.request_group_action(text, text, text, jsonb),\n  public.get_integration_runtime(), public.claim_channel_job(text), public.complete_channel_job(uuid, jsonb) from public, anon;\ngrant execute on function public.save_group_defaults(jsonb), public.request_group_action(text, text, text, jsonb) to authenticated;\ngrant execute on function public.group_action_is_read(text) to authenticated, service_role;\ngrant execute on function public.get_integration_runtime(), public.claim_channel_job(text), public.complete_channel_job(uuid, jsonb) to service_role;\n"},{"version":"010_n8n_testes.sql","sql":"-- ============================================================================\n-- 010 — Testes do n8n pelo painel (autoteste, webhooks de entrada, monitor e ciclo de envio)\n-- Só amplia a lista de ações aceitas por request_integration_action.\n-- ============================================================================\n\ncreate or replace function public.request_integration_action(p_provider text, p_action text, p_payload jsonb default '{}'::jsonb) returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v_id uuid; v_ok boolean; v_text text; v_payload jsonb := '{}'::jsonb; v_to text; v_ch text;\nbegin\n  perform public.require_admin();\n  v_ok := case p_provider\n    when 'evolution' then p_action in ('status', 'connect', 'restart', 'logout', 'set_webhook', 'create_instance', 'list_instances', 'send_test')\n    when 'telegram' then p_action in ('check', 'set_webhook', 'delete_webhook', 'send_test')\n    when 'mercadolivre' then p_action = 'check'\n    when 'shopee' then p_action = 'check'\n    when 'amazon' then p_action = 'check'\n    when 'n8n' then p_action in ('selftest', 'webhook_check', 'run_monitor', 'run_sender')\n    else false end;\n  if not coalesce(v_ok, false) then raise exception 'Ação não existe para esta integração'; end if;\n  v_ch := case p_provider when 'evolution' then 'whatsapp' when 'telegram' then 'telegram' else null end;\n\n  if p_action = 'run_sender' and public.setting_bool('paused', false) then raise exception 'Envios pausados: retome antes de rodar o ciclo de envio'; end if;\n\n  if p_action = 'send_test' then\n    if public.setting_bool('paused', false) then raise exception 'Envios pausados: retome antes de enviar o teste'; end if;\n    v_to := btrim(coalesce(p_payload ->> 'to', ''));\n    if p_provider = 'evolution' then\n      v_to := regexp_replace(v_to, '\\D', '', 'g');\n      if v_to !~ '^\\d{10,15}$' then raise exception 'Número inválido. Use DDI + DDD + número, só dígitos (ex.: 5511999990001)'; end if;\n    elsif v_to !~ '^(-?\\d{5,20}|@[A-Za-z][A-Za-z0-9_]{4,31})$' then raise exception 'Destino inválido: ID numérico do chat ou @canal';\n    end if;\n    v_text := left(btrim(coalesce(p_payload ->> 'text', 'Teste da Central de Promoções: a integração está funcionando.')), 500);\n    if array_length(public.text_violations(v_text), 1) > 0 then raise exception 'O texto contém termos proibidos'; end if;\n    v_payload := jsonb_build_object('to', v_to, 'text', v_text);\n  elsif p_provider = 'evolution' and p_action = 'connect' then\n    v_to := regexp_replace(coalesce(p_payload ->> 'pairing_number', ''), '\\D', '', 'g');\n    if v_to <> '' and v_to !~ '^\\d{10,15}$' then raise exception 'Número para código de pareamento inválido'; end if;\n    if v_to <> '' then v_payload := jsonb_build_object('pairing_number', v_to); end if;\n  end if;\n\n  -- repetição de clique: reaproveita a tarefa idêntica em andamento\n  select id into v_id from public.channel_jobs\n   where kind = 'integration' and status in ('pending', 'claimed') and payload ->> 'provider' = p_provider and payload ->> 'action' = p_action\n     and requested_at > now() - interval '60 seconds' limit 1;\n  if found then return v_id; end if;\n  if (select count(*) from public.channel_jobs where kind = 'integration' and requested_by = auth.uid() and requested_at > now() - interval '1 minute') >= 12 then\n    raise exception 'Muitas ações seguidas. Aguarde um minuto';\n  end if;\n  -- QR codes antigos não ficam guardados\n  update public.channel_jobs set result = null where kind = 'integration' and result ? 'qr' and finished_at < now() - interval '10 minutes';\n  insert into public.channel_jobs (kind, channel, payload, requested_by)\n  values ('integration', v_ch, jsonb_build_object('provider', p_provider, 'action', p_action) || v_payload, auth.uid()) returning id into v_id;\n  perform public.log_audit('integration_action', 'integration', p_provider || ':' || p_action, '{}'::jsonb);\n  return v_id;\nend $$;\n\nrevoke all on function public.request_integration_action(text, text, jsonb) from public, anon;\ngrant execute on function public.request_integration_action(text, text, jsonb) to authenticated;\n"},{"version":"011_database_providers.sql","sql":"-- ============================================================================\n-- 011 — Provedores de banco e atualização controlada de migrações\n--\n-- Este arquivo é o bootstrap da atualização automática. Aplique-o uma vez no\n-- SQL Editor. Depois disso o worker pode aplicar somente arquivos posteriores,\n-- usando token da Management API guardado apenas no cofre de segredos.\n-- ============================================================================\n\ncreate table if not exists public.app_schema_migrations (\n  version text primary key check (version ~ '^\\\\d{3}_[a-z0-9_]+\\\\.sql$'),\n  applied_at timestamptz not null default now(),\n  applied_by text not null default 'bootstrap',\n  checksum text\n);\nalter table public.app_schema_migrations enable row level security;\nrevoke all on public.app_schema_migrations from public, anon;\ngrant select on public.app_schema_migrations to authenticated;\ngrant all on public.app_schema_migrations to service_role;\ncreate policy read_member on public.app_schema_migrations for select to authenticated using (public.is_member());\n\ninsert into public.app_schema_migrations(version, applied_by) values\n  ('001_schema.sql', 'bootstrap'), ('002_core_functions.sql', 'bootstrap'),\n  ('003_publication_functions.sql', 'bootstrap'), ('004_reporting.sql', 'bootstrap'),\n  ('005_security_and_seed.sql', 'bootstrap'), ('006_chats.sql', 'bootstrap'),\n  ('007_categorias_grupos_conectores.sql', 'bootstrap'), ('008_integracoes.sql', 'bootstrap'),\n  ('009_grupos_acoes.sql', 'bootstrap'), ('010_n8n_testes.sql', 'bootstrap'),\n  ('011_database_providers.sql', 'bootstrap')\non conflict (version) do nothing;\n\ninsert into public.settings(key, value) values\n  ('int_database', '{\"provider\":\"supabase\",\"project_ref\":\"\",\"api_url\":\"\",\"migration_mode\":\"manual\"}'::jsonb)\non conflict (key) do nothing;\n\n-- Só nomes e estado são retornados ao painel. O token da Management API nunca sai\n-- de integration_secrets e não é enviado pelo get_database_overview.\ncreate or replace function public.get_database_overview() returns jsonb\nlanguage plpgsql stable security definer set search_path = public as $$\ndeclare cfg jsonb;\nbegin\n  if not public.is_member() then raise exception 'Sem permissão' using errcode = '42501'; end if;\n  select value into cfg from public.settings where key = 'int_database';\n  return jsonb_build_object(\n    'config', coalesce(cfg, '{}'::jsonb),\n    'migration_count', (select count(*) from public.app_schema_migrations),\n    'latest', (select max(version) from public.app_schema_migrations),\n    'management_token_configured', exists (select 1 from public.integration_secrets where key = 'supabase_management_token')\n  );\nend $$;\n\ncreate or replace function public.save_database_config(p_config jsonb) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare p text; r text; u text; m text;\nbegin\n  perform public.require_admin();\n  if jsonb_typeof(p_config) <> 'object' then raise exception 'Configuração inválida'; end if;\n  if exists (select 1 from jsonb_object_keys(p_config) k where k not in ('provider','project_ref','api_url','migration_mode')) then\n    raise exception 'Campo de banco desconhecido';\n  end if;\n  p := coalesce(btrim(p_config ->> 'provider'), 'supabase');\n  if p not in ('supabase','postgresql','future') then raise exception 'Provedor inválido'; end if;\n  r := btrim(coalesce(p_config ->> 'project_ref', ''));\n  u := regexp_replace(btrim(coalesce(p_config ->> 'api_url', '')), '/+$', '');\n  m := coalesce(btrim(p_config ->> 'migration_mode'), 'manual');\n  if p = 'supabase' and r <> '' and r !~ '^[a-z0-9]{20}$' then raise exception 'Project ref do Supabase inválido'; end if;\n  if u <> '' and not public.valid_https_url(u) then raise exception 'API URL inválida; use https'; end if;\n  if m not in ('manual','worker') then raise exception 'Modo de migração inválido'; end if;\n  if p <> 'supabase' and m = 'worker' then raise exception 'Atualização pelo worker está disponível somente para Supabase'; end if;\n  insert into public.settings(key, value, updated_by) values ('int_database', jsonb_build_object('provider',p,'project_ref',r,'api_url',u,'migration_mode',m), auth.uid())\n  on conflict (key) do update set value = excluded.value, updated_by = excluded.updated_by, updated_at = now();\n  perform public.log_audit('database_config_saved', 'integration', p, jsonb_build_object('provider',p,'migration_mode',m,'has_project_ref',r <> '', 'has_api_url',u <> ''));\nend $$;\n\ncreate or replace function public.set_supabase_management_token(p_value text) returns void\nlanguage plpgsql security definer set search_path = public as $$\ndeclare v text := btrim(coalesce(p_value, ''));\nbegin\n  perform public.require_admin();\n  if length(v) not between 20 and 500 or v ~ '\\\\s' then raise exception 'Token de gerenciamento inválido'; end if;\n  insert into public.integration_secrets(key,value,hint,updated_by) values ('supabase_management_token',v,right(v,4),auth.uid())\n  on conflict (key) do update set value=excluded.value,hint=excluded.hint,updated_by=excluded.updated_by,updated_at=now();\n  perform public.log_audit('database_management_token_set','integration','supabase','{}'::jsonb);\nend $$;\n\ncreate or replace function public.request_database_migration() returns uuid\nlanguage plpgsql security definer set search_path = public as $$\ndeclare cfg jsonb; v_id uuid;\nbegin\n  perform public.require_admin();\n  select value into cfg from public.settings where key = 'int_database';\n  if coalesce(cfg ->> 'provider','') <> 'supabase' then raise exception 'Atualização automática ainda não está disponível para este provedor'; end if;\n  if coalesce(cfg ->> 'migration_mode','manual') <> 'worker' then raise exception 'Escolha atualização pelo worker antes de solicitar'; end if;\n  if coalesce(cfg ->> 'project_ref','') = '' then raise exception 'Informe o project ref do Supabase'; end if;\n  if not exists (select 1 from public.integration_secrets where key='supabase_management_token') then raise exception 'Configure o token de gerenciamento; ele fica oculto após salvar'; end if;\n  select id into v_id from public.channel_jobs where kind='integration' and status in ('pending','claimed') and payload ->> 'provider'='database' and payload ->> 'action'='apply_migrations' order by requested_at desc limit 1;\n  if found then return v_id; end if;\n  insert into public.channel_jobs(kind,channel,payload,requested_by) values ('integration',null,jsonb_build_object('provider','database','action','apply_migrations'),auth.uid()) returning id into v_id;\n  perform public.log_audit('database_migration_requested','integration','supabase',jsonb_build_object('job',v_id));\n  return v_id;\nend $$;\n\ncreate or replace function public.get_integration_runtime() returns jsonb\nlanguage sql stable security definer set search_path = public as $$\n  select jsonb_build_object(\n    'evolution', coalesce((select value from public.settings where key='int_evolution'),'{}'::jsonb),\n    'telegram', coalesce((select value from public.settings where key='int_telegram'),'{}'::jsonb),\n    'n8n', coalesce((select value from public.settings where key='int_n8n'),'{}'::jsonb),\n    'database', coalesce((select value from public.settings where key='int_database'),'{}'::jsonb),\n    'paused', public.setting_bool('paused',false),\n    'status', coalesce((select jsonb_object_agg(substr(key,12),value) from public.settings where key like 'int\\\\_status\\\\_%'),'{}'::jsonb),\n    'secrets', coalesce((select jsonb_object_agg(key,value) from public.integration_secrets),'{}'::jsonb),\n    'connectors', coalesce((select jsonb_object_agg(platform,jsonb_build_object('mode',mode,'config',config)) from public.connectors),'{}'::jsonb)\n  )\n$$;\n\ncreate or replace function public.report_integration_status(p_provider text, p_status jsonb) returns void\nlanguage plpgsql security definer set search_path = public as $$\nbegin\n  if p_provider not in ('evolution','telegram','n8n','mercadolivre','shopee','amazon','database') then raise exception 'Integração desconhecida'; end if;\n  if jsonb_typeof(p_status) <> 'object' or length(p_status::text) > 8000 then raise exception 'Estado inválido ou grande demais'; end if;\n  insert into public.settings(key,value) values ('int_status_' || p_provider,p_status || jsonb_build_object('checked_at',now()))\n  on conflict (key) do update set value=excluded.value,updated_at=now();\nend $$;\n\nrevoke all on function public.get_database_overview(),public.save_database_config(jsonb),public.set_supabase_management_token(text),public.request_database_migration() from public,anon;\ngrant execute on function public.get_database_overview(),public.save_database_config(jsonb),public.set_supabase_management_token(text),public.request_database_migration() to authenticated;\ngrant execute on function public.get_integration_runtime(),public.report_integration_status(text,jsonb) to service_role;\n"}],
  env: { has_url: !!SB, has_key: !!KEY, supabase_host: hostOfUrl(SB) },
  rpc: async (name, args) => {
    if (!SB || !KEY) throw new Error(MISSING);
    const r = await http({ method: 'POST', url: SB + '/rest/v1/rpc/' + name, headers: { apikey: KEY, Authorization: 'Bearer ' + KEY }, json: args || {}, timeoutMs: 30000 });
    if (r.status >= 300) throw new Error('Supabase ' + name + ' respondeu ' + r.status + ': ' + (r.data && (r.data.message || JSON.stringify(r.data)) || '').toString().slice(0, 200));
    return r.data;
  },
};

